INSERT INTO `faq` (`category`, `question`, `answer`, `source`) VALUES
('상품·보장 안내', '[상해]일반상해와 교통상해의 차이점은 무엇인가요?', '교통상해는 운전중 차량 탑승중 또는 비탑승중 자동차 및 기타교통수단과의 충돌 접촉으로 발생한 교통사고를 말하며 일반 상해는 교통사고를 포함한 급격하고도 우연한 외래의 사고로 신체에 입는 상해사고를 말합니다.', '하나손해보험'),
('상품·보장 안내', '[상해]교통승용구란 무엇을 말합니까?', '① 기차 전동차 기동차 케이블카(공중케이블카를 포함) 리프트 엘리베이터 및 에스컬레이터 모노레일 ② 자동차(자동차관리법 시행규칙 제 2조에 정한 승용자동차 승합자동차 화물자동차 특수자동차 및 이륜자동차) 스쿠터 자전거 원동기를 붙인 자전거 ③ 항공기 선박(요트 모터보트 보트를 포함) ④ 건설기계 농업기계(다만 이들이 작업기계로 사용되는 동안은 교통승용구로 보지 않음)', 'AXA'),
('상품·보장 안내', '[상해]교통상해란 어떤 경우를 말합니까?', '교통승용구에 의한 접촉 충돌 전복 추락 등으로 인하여 신체에 손상이 생긴경우를 말합니다. 승객 또는 운전자로서 교통승용구에 탑승하고 있을 때 일어난 사고와 승객이 아닌 보행자로서 교통승용구와의 접촉에 의해 일어난 사고를 포함합니다.', 'AXA'),
('상품·보장 안내', '대인배상 I 과 대인배상 II 의 차이가 무엇인가요?', '대인배상 I 이란 피보험자가 피보험자동차의 소유 사용 관리로 인하여 남을 죽게 하거나 다치게 하여 법률상 배상책임을 지는 경우 보상하는 담보로서 차량의 소유주라면 법적으로 가입이 강제화 되어 있는 담보입니다. 대인 배상II 란 피보험자가 피보험자동차를 소유 사용 관리하는 동안에 생긴 피보험자동차의 사고로 인하여 남을 죽게 하거나 다치게 하여 법률상 손해 배상책임을 짐으로써 입은 손해중 대인배상I(책임보험)의 보상한도를 초과하는 손해를 보상하는 담보입니다. 자동차 사고는 대부분 과실 사고이므로 피해자와 합의하거나 자동차보험의 대인배상 I 대인배상 II(무한) 및 대물배상 2천만원 이상의 보험에 가입한 경우에 는 합의한 것으로 간주하여 형사처벌이 면제됩니다. 대인배상I 대인배상II 모두 1인당 보상금액이고 1사고당 한도액은 없습니다. 그러므로 다친 사람 모두 대인배상의 한도내에서 보상이 가능합니다.', 'AXA'),
('상품·보장 안내', '자동차보험에서 안내해준 차량가액이 타사와 틀립니다.', '자동차제조회사에서 국가에 차량가액을 공시하면 이는 보험개발원의 공동전산망에 입력이 됩니다. 보험료 산출시 차량가액을 보험개발원을 통해 조회하기 때문에 모든 보험회사가 동일하게 적용하고 있습니다. 그러므로 연식과 차종 모델명 추가장착 부속품등을 확인하시어 동일한 차종으로 적용하시면 차량가액 또한 동일합니다. 하지만 추가적으로 장착한 부속품이 있는 경우에는 부속가액이 포함되므로 차량가액의 차이는 발생할 수 있습니다. 타사와 동일한 조건으로 비교하시어 합리적인 곳으로 가입하시기를 권해드립니다', 'AXA'),
('상품·보장 안내', '자기신체사고와 자동차상해의 차이점은 무엇입니까?', '자기신체사고와 자동차상해는 사고시 피보험자와 탑승한 직계가족의 신체에 대한 손해를 보상하는 담보로써 보상의 개념은 동일하나 자동차상해 담보가 좀 더 확장된 보상이 가능합니다. 예를 들면 부상시 자기신체사고에서는 부상등급별로 보상이 지급되지만 자동차 상해는 의료비 치료비에 대한 실손보상이 가능합니다. 또한 위자료 휴업손해비 등을 별도로 지급합니다. 동일한 가입한도일 경우에도 자동차 상해 담보가 보상의 범위가 크다고 할 수 있습니다. 그러므로 가입시 자동차상해를 선택하실 경우 자기신체사고를 선택하실 때보다 보험료가 좀 더 올라가게 됩니다. 자기신체사고의 경우 사망/후유장해 1천5백만원 3천만원 5천만원 1억까지 선택이 가능하나 부상은 1천 5백만원으로 동일합니다. 자동차상해의 경우 사망 / 후유장해는 1억 2억 3억 5억 10억까지 선택이 가능하고 부상은 1천만원 2천만원 3천만원 5천만원 중 선택이 가능합니다.', 'AXA'),
('상품·보장 안내', '업무용 자동차보험이란 무엇입니까?', '자동차보험이란 피보험자가 피보험자동차를 소유 사용 또는 관리하는 과정에서 발생하는 사고로 인하여 다른 사람(타인)의 신체를 사상하거나 남의 재물을 멸실 파손 또는 오손시켜 법률상 손해배상책임을 짐으로써 입은 손해와 피보험자 자신이 죽거나 다침으로써 입은 손해 및 피보험자동차 자체에 발생한 손해를 보상하는 보험입니다. 차량 소유자가 개인인 자가용 승합차(법정승차정원 11인승 이상) 화물차 및 법인이 소유한 자가용 승용차 승합차 화물차 건설기계 등이 가입대상입니다.', 'AXA'),
('상품·보장 안내', '개인용 자동차보험이란 무엇입니까?', '자동차보험보험이란 피보험자가 피보험자동차를 소유 사용 또는 관리하는 과정에서 발생하는 사고로 인하여 다른 사람(타인)의 신체를 사상하거나 남의 재물을 멸실 파손 또는 오손시켜 법률상 손해배상책임을 짐으로써 입은 손해와 피보험자 자신이 죽거나 다침으로써 입은 손해 및 피보험자동차 자체에 발생한 손해를 보상하는 보험입니다. 차량소유자가 개인인 자가용승용차로 자동차보험을 가입하는 경우 개인용 자동차보험 가입대상입니다.승용자동차의 범위는 법정승차정원 10인이하의 승용자동차(다인승 승용자동차 포함)입니다.', 'AXA'),
('가입·보험료', '기본정보에 입력하는 사람과 보험에 가입하는 사람이 동일해야 하나요?', '보험료를 정확히 계산하기 위하여 고객님이 이전에 가입하신 보험경력을 조회 하여야 하기 때문에 기본정보란에는 보험에 가입하는 차량을 소유한 분의 정보 를 입력하셔야 합니다. 만약 타인을 대신하여 보험료를 산출하시더라도 차량을 실제 소유하고 있는 사람의 정보를 입력해 주셔야 합니다.', 'AXA'),
('가입·보험료', '책임보험만 타사에 가입하고 있는데 종합보험만 에 가입할수 있나요?', '책임보험과 종합보험은 같은 보험사에 가입을 하셔야 사고 처리가 원활하게 이루어 질수 있습니다.또한 책임보험을 제외한 임의보험(종합보험)만 따로 가입하실 수 있는 보험사는 없습니다. 책임보험과 종합보험을 모두 같은 보험사에 가입하셔야 사고시 신속하고 정확한 보상을 받으실 수 있습니다.', 'AXA'),
('가입·보험료', '적용보험료란 무엇입니까?', '기본보험료에 당해 계약에 해당하는 제반 요율요소를 적용하여 산출한 금액으로 보험계약자가 납입하여야 할 보험료를 말합니다.', 'AXA'),
('가입·보험료', '기본보험료란 무엇입니까?', '적용보험료 산정의 기본이 되는 보험료로서 차량의 종류 담보종목 담보가입금액 등 제반 요소에 의해 정해집니다. 매년 차종별로 손해율 및 사고발생빈도 등의 위험도를 분석하여 기본보험료를 책정하며 금융감독원의 인가를 받아 적용하고 있습니다.', 'AXA'),
('가입·보험료', '자기차량사고 가입금액은 얼마가 적정합니까?', '자기차량손해담보는 피보험자가 피보험자동차를 소유 사용 관리하는 동안에 생긴 피보험자동차의 직접손해를 보험가입금액 한도내에서 보상하는 담보입니다. 자기차량손해 가입금액은 자동차제조회사에서 국가에 차량가액으로 공시하면 이는 보험개발원이라는 보험회사 공동전산망에 입력이 됩니다. 보험료 산출시 차량가액은 보험개발원을 통해 조회하므로 모든 보험회사가 동일하게 적용하고 있습니다. 그러므로 고객님께서 가입금액을 정할 수 없으며 이점 양지하여 주시기바랍니다.', 'AXA'),
('가입·보험료', '보험가입금액이란 무엇인가요?', '자동차보험 가입시 담보종목별로 보장해주는 한도금액을 정할 수 있으며 그 한도를 가입금액이라고 합니다. 사고시 보험증권에 기재된 가입금액을 한도로 보험금이 지급됩니다.', 'AXA'),
('가입·보험료', '카드로 결제시 다른 사람 카드로 되나요?', '보험료를 산출하고 카드로 결제하실 때 피보험자가 아닌 다른 가족의 카드로 대신 결제하실 수 있습니다. 피보험자가 아닌 가족의 카드로 결제하셔도 정상적인 계약체결에는 아무런 문제가 없으므로 걱정하지 않으셔도 됩니다. 단 보험료를 납부하신 분(카드소유주)이 자동차보험의 계약자로 등록이되며 보험계약자가 해지 변경 연말정산등의 혜택이 가능합니다. 그리고 계약사항 중도에 변경하여 추가보험료를 결제할 경우 계약자의 카드로만 결제가능합니다.', 'AXA'),
('가입·보험료', '가입설계서에 법규위반항목이 마이너스(음수)로 되어있는데 이것은 무엇을 말하는 것입니까?', '고객님께서 법규위반사항이 없는 경우마이너스로 표시된 요율이 가입경력율에서 할인된다는 것을 나타내은 것입니다. 즉 법규위반사항이 없다는 것을 나타냅니다.', 'AXA'),
('가입·보험료', '신차의 경우 차량 번호가 나오기 전에도 보험에 가입할 수 있습니까?', '차량번호가 나오기 전에도 보험가입이 가능하며 차대번호 출고증번호 매매계약서번호 중 하나로 보험에 가입하실 수 있습니다.', 'AXA'),
('가입·보험료', '공제조합에 가입한 경력도 보험가입시 인정됩니까?', '공제조합에 가입한 보험가입경력도 보험사에서 인정받을 수 있습니다. 그러나 공제조합에서 적용 받았던 적용등급은 보험사에서 인정하지 않습니다.', 'AXA'),
('가입·보험료', '군에서 운전병으로 복무한 경력도 보험가입시 인정됩니까?', '가입경력율이란 고객님께서 자동차 보험에 가입한 기간을 보험료에 적용 받게되는 요율입니다. 군대 관공서 법인체 등에서 운전직으로 근무한 경우 근무기간 만큼을 가입경력으로 포함되어 할인적용을 받으실 수 있으며 군에서의 운전경력을 인정받기 위해서는 병무청에서 발급하는 병적증명서가 필요하며 관공서 법인체의 운전경력은 경력증명서를 제출하면 운전경력이 인정됩니다. 단 반드시 직종이 운전직 또는 운전병으로 기입이 되어야 합니다', 'AXA'),
('가입·보험료', '외국에서의 보험가입경력도 인정받을 수 있습니까?', '가입경력율이란 고객님께서 자동차 보험에 가입한 기간을 보험료에 적용 받게되는 요율입니다. 외국 체류기간 중 차량을 운행하여 보험을 가입하셨다면 가입경력율에 포함되어 할인적용을 받으실 수 있으며 해외에서 가입한 보험료 납입영수증 증권 기타 보험가입사실을 확인할 수 있는 서류와 외국체류기간을 확인할 수 있는 여권 사본 등을 첨부하여 제출하시면 가입경력으로 인정이 됩니다. 하지만 외국에서의 보험가입기간 중에 발생한 사고에 따른 보험료의 할인 및 할증 요율은 인정되지 않습니다.', 'AXA'),
('가입·보험료', '2대 이상의 차량 보유한 경우에 보험에 어떻게 가입하는게 유리합니까?', '자가용 승용차를 한 사람의 명의로 두 대 이상 소유하는 경우에는 하나의 증권으로 묶어서 가입하시는 것이 유리합니다. 하나의 증권으로 가입하지 않는 경우에는 사고가 발생했을 때 사고발생차량 뿐만 아니라 다른 차량에도 사고로 인해 보험료가 할증되지만 하나의 증권으로 가입한 경우에는 사고차량은 할증된 요율로 사고가 없는 차량은 할인된 요율을 적용한 후 이를 산술 평균한 요율을 모든 차량에 적용하므로 사고 후 갱신시 동일증권으로 가입을 하시면 보험료를 절약 할 수 있습니다.', 'AXA'),
('특약·할인', '자기차량손해 사고부대비용담보 특별약관은 무엇인가요?', '자기차량손해 사고부대비용담보 특약은 전손시 제반 비용과 원격지 사고시 차량운반비용에 대한 부분의 보상이 가능합니다. 전손시 제반비용 보험금은 100만원을 한도로 보험증권에 기재된 보험가입금액의 7%에 해당하는 금액을 지급합니다. 또한 원격지에서 사고가 발생했을 때 차량운반비용 보험금은 20만원 한도내에서 비용을 지급합니다.', 'AXA'),
('특약·할인', '렌트비용 지원 특별약관은 무엇인가요?', '렌터비용 지원 특별약관은 자기차량손해 담보의 보험금이 지급되는 경우로 피보험자동차를 사용할 수 없게 된 기간 동안에 피보험자동차와 동급의 국내산 렌터카를 제공드립니다. 렌터카 사용을 안하실 경우에는 피보험자동차와 동급의 국내산 렌터카 대여비용의 35%를 지급해 드리며 개인용자동차보험과 업무용자동차보험의 승용 및 경/3종 승합자동차에만 판매를 하고 있습니다.', 'AXA'),
('특약·할인', '가족 및 형제자매 운전자 한정운전 특별약관은 무엇입니까?', '가족 및 형제자매 운전자 한정운전특약이란 차량의 운전범위를 고객님의 가족 및 형제자매로 제한하여 고객님께 보다 합리적인 보험료를 제시해 드리는 특별약관입니다. 기존의 가족운전한정특약의 범위는 기명피보험자 배우자 부모 및 자녀로 제한되므로 형제 및 자매와 함께 운행하시려면 가족 및 형제자매 운전자 한정운전 특약으로 가입하시면 됩니다.', 'AXA'),
('특약·할인', '다른자동차 운전담보 특별약관이란 무엇입니까?', '무보험자동차에 의한 상해담보 가입시 ''다른 자동차 운전담보 특약''에 자동담보됩니다. 이 특약은 피보험자와 피보험자의 배우자가 다른 자동차를 운전 중 대인사고나 대물사고를 일으켰거나 본인이 상해를 입었을때 피보험자가 가입한 자동차보험의 대인배상II 대물배상 자기신체사고(자동차상해)를 적용하여 보상합니다. ''다른 자동차''의 개념은 동일한 차종이면서 기명피보험자와 그 부모 배우자 자녀가 소유하거나 통상적으로 사용하는 자동차가 아닌 것입니다.(승용자동차 경승합자동차 및 경 4종화물자동차간에 다인승1종 2종 승용자동차 3종승합자동차간에는 동일한 차종으로 봅니다.) 피보험자와 피보험자의 배우자가 다른 차량을 운전하시다 사고가 나셨을 경우 운전하신 차량의 보험에서 보상이 안될 시에는 피보험자가 가입하신 무보험차상해 담보에서 보상이 가능하나 피보험자와 피보험자의 배우자가 운전하신 차량은 보상이 되지 않으므로 피보험자가 자비로 처리하셔야 합니다.', 'AXA'),
('특약·할인', '운전자연령한정특약이란 무엇입니까?', '자동차를 운전하는 사람의 연령(주민등록상 기준)을 한정하는 것으로 만연령이 설정된 연령 범위내의 운전자가 운전을 하도록 운전 연령을 한정으로 하여 위험을 줄이고 보험료를 할인받는 특약입니다. 운전자연령한정특약에 가입하시면 한정된 연령 범위 이외의 사람이 자동차를 운전하다 사고가 발생할 경우 보상받지 못하게 되므로 유의해야 합니다', 'AXA'),
('특약·할인', '가족운전한정특약에서 말하는 가족의 범위는 무엇입니까?', '가족운전한정특약은 자동차를 운전할 수 있는 범위를 피보험자와 그 가족으로 한정하는 특별약관으로서 가족의 범위는 다음과 같습니다.피보험자의 부모 또는 양부모 피보험자 또는 배우자의 부모와 양부모 및 계부모 법률상의 배우자 또는 사실혼 관계에 있는 배우자 법률상의 혼인관계에서 출생한 자녀 사실혼 관계에서 출생한 자녀 양자 또는 양녀 계자녀 며느리 및 사위가 포함됩니다.', 'AXA'),
('특약·할인', '다른 자동차 운전담보 특별약관에서 피보험자 및 보상범위는 어떻게 됩니까?', '피보험자는 기명 피보험자 및 기명 피보험자의 배우자로 한정됩니다. 이때 회사는 피보험자가 다른 자동차를 운전중(주차 또는 정차중을 제외합니다) 생긴 대인사고나 대물사고로 인하여 법률상 손해배상책임을 짐으로써 손해를 입은 때 또는 피보험자 또는 탑승한 다른자동차의 소유주가 상해를 입었을 때에는 피보험자가 운전한 다른 자동차를 보통 약관의 대인배상Ⅱ 대물배상 자기신체사고 규정의 피보험자동차로 간주하여 보통 약관에서 규정하는 바에 따라 보상합니다.', 'AXA'),
('특약·할인', '거주하는 주택에서 화재가 발생하여 이웃한 건물에 피해를 입었을 경우에는 화재손해특약에서 보상이 가능한 가요?', '보험 가입 목적물에 발생한 화재로 인해 이웃한 건물에 피해 발생시 가입된 목적물 외에는 화재손해특약에서 보상하지 않습니다. 다만 특별약관을 추가(화재배상책임 화재대물배상책임) 가입하신 경우는 보상이 가능합니다.', 'AXA'),
('특약·할인', '화재손해특약에서 보상하는 손해는 어떤건가요?', '화재손해담보는 특별약관에 명시된 ①화재에 따른 직접손해 ②화재에 따른 소방손해 ③화재에 따른 피난손해를 보상하고 있습니다. (또한 주택화재보험은 폭발 파열손해도 포함하고 있습니다.) 그 밖의 위험에 대해서는 특별약관을 추가함으로써 보상이 가능합니다.', 'AXA'),
('계약관리·변경', '[상해]소멸성이면 만기환급금이 없어 고객입장에선 손해가 아닌가요?', '동일한 보험가입금액 기준으로 1년 소멸성인 순수보장형 상품의 보험료보다 만기환급금이 있는 보험료가 훨씬 높습니다. 그러나 20년이 지난 뒤의 만기환급금은 납입 원금에 불과하고 또한 20년 뒤의 화폐가치를 감안하면 만기시 환급금은 굉장히 적은 금액입니다.따라서 보험은 소멸성으로 들고 저축은 은행을 통하여 하는 것이 현명한 방법입니다.', 'AXA'),
('계약관리·변경', '보험 가입 후 보험증권은 언제 받아볼 수 있나요?', '보험가입 시 고객님께서는 보험증권팩(증권 음성녹음확인서 또는 청약서 상품설명서 약관)을 ''우편'' 또는'' E-mail'' 또는 ''Mobile 앱'' 전자문서 중 선택이 가능합니다. 우편을 선택하신 경우 일반우편으로 발송이 되어 고객님이 받아보시는 데는 약 1주일 정도 소요가 되니 전자증권도 법적으로 종이증권과 동일한 효력을 갖고 보험가입 즉시 안전하게 확인 하시고 친환경을 함께 실천하는 전자문서(E-mail 또는 Mobile 앱)를 선택하시는 것을 추천 권해드립니다.', 'AXA'),
('계약관리·변경', '[전자보험거래표준약관]전자보험거래시 계약정보 및 관련 데이타를 언제까지 보관하나요?', '회사는 전자거래의 기록을 보험계약 소멸일부터 5년간 보존합니다. 또한 회사는 이용자의 요청이 있을 경우 금융실명거래및비밀보장에관한법률 등 관계법률에 저촉되지 않는 범위내에서 회사가 보존ㆍ관리하고 있는 전자거래와 관련된 기록 및 자료를 당해 이용자에게 제공하여야 합니다.', 'AXA'),
('계약관리·변경', '만기알림이란 무엇인가요?', '자동차보험은 일정한 시점(신차구입 또는 보험만기)에서 가입할 수 있으므로 홈페이지를 방문하셨더라도 손해보험 자동차보험에 가입하지 못하는 경우가 있습니다. 미리 만기알림 신청을 하시면 고객님의 보험만기가 다가오면 직접 연락을 드리는 서비스입니다.', 'AXA'),
('계약관리·변경', '피보험자와 보험계약자는 무엇이 다른가요?', '피보험자는 차량을 소유하고 있는 사람 즉 차량등록증상에 소유자로 되어 있는 사람을 말하며 등록증상의 소유자를 피보험자로 하셔야 사고가 발생했을 때 보상을 받으실 수 있습니다. 계약자는 보험료를 납입하는 사람을 말하며 보험료를 납입하는 분께서 연말정산 소득공제 혜택을 받으실 수 있습니다. 피보험자와 보험계약자를 다르게 하여 가입을 하신 경우 피보험자 계약자 두분 모두 소득이 있는 경우에는 피보험자와 계약자가 동일해야 소득공제 혜택을 받으실 수 있습니다. 소득공제 혜택 범위는 본인 배우자 부양가족 명의로 가입한 보장성 보험에 한합니다.', 'AXA'),
('계약관리·변경', '납입유예기간이란 무엇입니까?', '보험료 분할납입특약으로 가입하여 약정한 납입일자까지 2회이후 분할보험료가 납입되지 않은 경우 납입일자로부터 30일간의 납입최고기간을 두며 납입최고기간 말일까지도 분할보험료가 납입되지 않은 경우에는 납입최고기간이 끝나는 날의 24시부터 보험계약이 해지됩니다.', 'AXA'),
('계약관리·변경', '자동차등록증상 소유주와 자동차보험 피보험자(가입자)가 다른경우 가입이 가능한가요?', '자동차보험가입시 피보험자는 차량을 소유하고 있는 사람 즉 차량등록증상에 소유자로 되어 있는 사람을 피보험자로 하셔야 사고가 발생했을 때 보상을 받으실 수 있습니다. 그러므로 자동차등록증상의 소유주와 자동차보험의 기명피보험자는 동일하여야 합니다.', 'AXA'),
('계약관리·변경', '동일증권이란 무엇입니까?', '동일증권이란 피보험자가 차량을 2대 이상 가지고 있는 경우 하나의 증권(계약)을 원계약으로 하고 이 원계약에 다른 계약을 추가하여 동일한 증권번호로 계약을 체결하는 것을 말합니다. 동일증권 가입 조건은 1)가입회사가 동일하고 2)승용자동차 보험(개인용계열 자동차보험) 또는 개인소유 업무용 소형차(경승합차 1톤이하 화물차)인 경우에만 가능합니다. 동일증권으로 가입하면 보험기간이 동일하여 계약관리가 용이하며 사고 발생 시 할인할증율 적용에 유리합니다. 즉 사고가 발생했을때 동일증권으로 가입하지 않았을 경우에는 사고발생 차량뿐만 아니라 다른 나머지 차량에도 사고로 인한 할증율이 적용되지만 동일증권으로 가입한 경우에는 사고차량은 할증된 요율로 사고가 없는 차량은 할인된 요율로 적용한 후 이를 합산하여 동일증권 차량댓수로 산술 평균한 요율을 모든 차량에 적용하도록되어 있어 차가 2대 이상인 경우에는 동일증권으로 가입하는 것이 유리합니다.', '하나손해보험'),
('계약관리·변경', '인터넷으로 계약변경을 할 수 있습니까?', '보험가입 후 계약사항을 변경하시려면 홈페이지 [My] > [자동차보험 계약변경] 또는 [장기보험 계약변경] 메뉴를 이용해주세요.', 'AXA'),
('계약관리·변경', '장애인 차량 공동명의 등록할 수 있는 범위가 어떻게 되나요?', '장애인 차량의 공동명의로 등록할 수 있는 범위는 공동명의 가족(같은세대원)이어야 합니다.가족일 경우도 세대가 분리된 상태라면 공동명의는 불가능 합니다. ※장애인과 공동명의로 등록할 수 있는 가족은 직계존비속 비속의 배우자 형제/자매입니다.', 'AXA'),
('계약관리·변경', '외제차량 사고에 대비한 상품에 추가 가입하고 싶습니다.', '대물배상은 피보험자동차를 소유 사용 관리하는 동안에 생긴 피보험자동차의사고로 남의 재물을 멸실 파손 또는 오손하여 법률상 손해배상책임을 짐으로써 입은 손해를 가입금액에 따라 보상하는 담보입니다. 따라서 외제차와의 접촉사고를 대비하신다면 대물배상의 한도를 상향조정하여 가입하시면 됩니다. 대물배상 한도 변경을 원하실 경우 홈페이지에서 변경이 가능합니다.', 'AXA'),
('계약관리·변경', '현재 자동차보험이 어머니 앞으로 가입되어 있는데 운전은 제가 해서 저 앞으로 보험 가입하고 싶습니다.', '자동차보험의 기명피보험자는 반드시 자동차등록증상의 소유자를 피보험자로 가입하셔야 됩니다. 그러므로 자동차등록증상의 소유자와 자동차보험의 기명피보험자는 반드시 동일하셔야 합니다.어머님 차량을 고객님 앞으로 가입하시려면 자동차등록증상의 소유자를 고객님 앞으로 명의이전 하셔야 합니다.', 'AXA'),
('계약관리·변경', '증권을 재발급 받고 싶습니다. 어떻게 해야 하는지요?', '보험증권이란 보험회사와 보험계약자 사이에 계약의 체결과 그 체결 내용을 증명하고 보증하기 위해 보험계약자에게 교부는 증서입니다. 보험증권을 분실하였거나 또는 훼손되었을 경우 보험증권 재발행을 요청하실 수 있으며 재발행 요청은 모바일 및 인터넷 로그인 후 바로가기-[증명서 발급]- [해당계약 선택]-[발급할 문서선택]-[발급방법 선택]을 통해 이메일발송 및 미리보기 통한 다운로드 방법으로 발급이 가능합니다.', 'AXA'),
('계약관리·변경', '승차정원 및 적재적량등이 변경되었는데 어떻게 해야 하나요?', '최근 차량의 구조변경을 하시고 보험회사에 구조변경된 내용을 통지하셔서 차량등록증 상의 차종과 다른 차종으로 보험가입(또는 계약변경)을 요청하시는 경우가 있습니다.그러나 차량의 구조변경에 의해 승차인원 및 적재적량의 변경이 이루어졌다 하더라도 자동차 보험계약시 적용되는 차종분류 기준은 최초 차량이 출고되어 등록될 당시 적용되었던 차종(차량등록증에 기재된 차종)을 기준으로 합니다. 다만. 차량구조 변경에 투여된 비용은 차량가액의 증가분으로 산정하지 않고 부속품으로 산정하도록 되어 있습니다. 따라서 차량구조가 변경되었어도 최초 차종분류를 기준으로 보험에 가입하시면 됩니다.', 'AXA'),
('계약관리·변경', '보험가입증명서를 팩스로 받고 싶습니다.', '보험가입증명서 발급 요청은 모바일 및 인터넷 로그인 후 바로가기-[증명서 발급]- [해당계약 선택]-[발급할 문서선택]-[발급방법 선택]을 통해 이메일발송 및 미리보기 통한 다운로드 방법으로 발급이 가능합니다.', 'AXA'),
('계약관리·변경', '이메일로 소득공제용 보험료 납입증명서를 보내줄 수 있나요?', '소득공제용 납입증명서를 모바일 및 인터넷 로그인 후 바로가기-[증명서 발급]- [소득공제용 납입증명서]에서 발급방법을 [이메일 보내기] 선택하여 발급이 가능합니다.', 'AXA'),
('계약관리·변경', '연말정산을 위해 보험료납입증명서를 받고자 합니다. 어떻게 신청하여야 합니까?', '소득공제용 납입증명서를 모바일 및 인터넷 로그인 후 바로가기-[증명서 발급]- [소득공제용 납입증명서]에서 발급이 가능합니다.', 'AXA'),
('계약관리·변경', '자동차보험을 1년이 아닌 일정기간만 보험가입 할 수 있나요?', '자동차보험의 보험기간은 보험료 산출을 위한 위험측정상의 단위가 되는 기간을 말하는데 통상 1년을 기준으로 하여 보험료를 산출하기 때문에 현재로서는 1년을 기준으로 보험가입하도록 되어 있습니다. 하지만 일시적으로 차량을 구입한 경우이거나 1년미만의 기간을 정하여 보험가입도 가능합니다. 다만 1년 미만의 단기계약에 대해서는 별도의 단기요율을 적용하므로 대체적으로 보험료가 비싸집니다.', 'AXA'),
('계약관리·변경', '자차 차량가액을 낮추고 싶습니다.', '보험가입시 적용되는 차량가액은 차량의 연식 및 형식에 따라 보험개발원에서 정한 차량기준가액표에 의하여 산정되며 모든 보험사에서는 동일하게 적용하고 있습니다.자기차량손해담보를 가입하시는 경우 차량가액의 전부를 가입하시거나 일부보험이라 하여 차량가액을 60%이상으로 가입하실 수 있습니다. 피보험자동차에 직접적으로 생긴 손해는 보험가입금액 한도로 보상이 되며 만일 보험가입금액이 보험가액보다 많은 경우에는 보험가액을 한도로 보상합니다.', 'AXA'),
('사고접수·보상', '[상해]사고가 나지 않으면 보험료만 소멸되는 것 아닌가요?', '보험에 가입하더라도 대부분의 사람들에게는 거의 사고가 일어나지 않습니다. 그러나 나에게 사고가 일어난다면 고액보장을 받고 싶어합니다. 그래서 보장이 크고 보험료는 저렴한 1년짜리 소멸성 보험을 선호하게 됩니다. 저렴한 보험료로 유사시 큰 보장을 받을 수 있고 만기시에 소멸되는 보험이 선진국에서는 이미 보편화되어 있습니다. 많지 않은 사망보험금 2 ~3천만원을 보장받기 위해 매월 4 ~5만원씩 보험료를 내는 운전자보험이나 생명보험에 비하면 다이렉트상해보험은 훨씬 실속있고 합리적인 보험의 명품입니다. 보험에 가입하시는 순간 고객님은 보험의 명사에 속하게 됩니다.', 'AXA'),
('사고접수·보상', '사고로 인한 할증은 사고운전자에게 적용됩니까?', '사고로 인한 할증은 보험에 가입하는 차량의 사고 유무를 기준으로 하여 적용 됩니다. 예를 들어 갑이라는 사람이 부부한정운전 조건으로 자동차보험을 가입하신 후 갑의 배우자가 차량을 운전하다 사고가 발생했을 경우 사고 할증은 갑이 가입한 자동차보험에 적용됩니다.', 'AXA'),
('사고접수·보상', '사고로 인한 보험료할증은 어떻게 적용됩니까?', '자동차보험의 할인할증 제도는 등급제로 운영이 되고 있습니다. 사고가 없을 경우 등급이 상향되고 사고가 있을 경우 등급이 하향됩니다. 최초 신규 가입시 11등급으로 시작하여 무사고시 한등급씩 숫자가 올라가 최저 29등급까지 적용받게되며 사고가 있을 경우 사고점수 만큼 등급이 하향되어 최대 1등급까지 할증됩니다.사고로 인한 할증은 사고 후 3년간 적용됩니다. 즉 3년간은 할증이 된 보험료를 납입하여야 하며 이 기간 중 사고가 없었을 경우에는 그 다음 해부터 매년 한등급씩 상향됩니다.(적용 등급의 적용은 모든 보험회사가 동일하나 할인할증 등급에 따른 요율은 보험회사가 자율적으로 부과하게 됩니다.) 또한 과거 3년간 사고건수에 따라 적용되는 사고 건수별 요율을 적용받게 됩니다.3년간 무사고인 경우 할인을 받게 되며 사고건수가 높을 수 록 높은 할증률을 적용받게 됩니다.', 'AXA'),
('사고접수·보상', '자기차량손해담보의 자기부담금은 무엇인가요?', '자기차량손해담보 가입 시 자기부담금 이란 사고가 발생했을 때 손해액의 일정 비율을 피보험자가 부담하는 것을 말합니다. 자기부담금 20% 또는 30% 중에서 선택하실 수 있으며 최대 100만원 이하의 금액을 부담하게 됩니다.', 'AXA'),
('사고접수·보상', '타인명의로 가입되어 있는 차량을 운전할 경우 보상받을 수 있나요?', '무보험자동차에 의한 상해담보를 가입하실 경우 다른자동차 운전담보 특약이 자동으로 적용됩니다. 피보험자가 다른자동차를 운전중 생긴 대인사고나 대물사고로 인하여 법률상 손해배상책임을 짐으로써 손해를 입은 때 또는 피보험자가 상해를 입었을 때에는 고객님께서 가입되어 있는 대인배상II 대물배상 자기신체사고 또는 자동차 상해 담보로 보상을 제공해 드립니다. 하지만 운전하신(타인차량)차량에 대해서는 보상해드리기 어렵습니다. 이 경우라도 다른 자동차 차량손해담보추가 특별약관에 가입하시면 1천만원을 한도로 보상받을 수 있습니다.', 'AXA'),
('사고접수·보상', '자기신체사고로 가입했는데 자동차상해 담보로 변경이 가능한가요?', '자기신체사고와 자동차상해는 피보험자가 피보험자동차를 소유 사용 관리하는 동안에 생긴 피보험자동차의 사고로 인하여 죽거나 다친 때 그로 인한 손해를 보상하여 드립니다.자기신체사고와 자동차상해는 같은 개념이지만 자동차상해 담보가 좀더 확장된 보상이 가능합니다. 예를 들면 부상시 자기신체사고에서는 부상등급별로 보상이 지급되지만 자동차상해는 의료비 치료비에 대한 실손보상이 가능합니다. 또한 위자료 휴업손해비 등을 별도로 지급합니다. 따라서 자동차상해 담보가 보상의 범위가 크다고 할 수 있습니다. 자동차상해 담보는 사망/후유장해 1억원/부상 1천만원 또는 2천만원 또는 3천만원 또는 5천만원 사망/후유장해 2억원/부상 2천만원 또는 3천만원 또는 5천만원 사망/후유장해 3억원/부상 3천만원 또는 5천만원 사망/후유장해 5억원/부상 3천만원 또는 5천만원중 선택하실 수 있습니다. 변경을 원하실 경우 홈페이지에서 변경이 가능합니다.', 'AXA'),
('사고접수·보상', '자기차량손해담보(자차) 사고처리를 했는데 자기부담금을 납입해야 하나요?', '자기차량손해담보에서 자기부담금이란 자기차량손해 사고가 발생했을 때 일정한 금액을 피보험자가 부담하는 것을 말합니다.자기부담금은 공제면책금으로 자차수리시 수리공업사에 고객님께서 납부하셔야 합니다.', 'AXA'),
('사고접수·보상', '렌터카 사용료의 지급기준은 어떻게 됩니까?', '렌터카 사용료는 대물 손해로 보상해 드리고 자차 수리를 하는 경우에는 보상해 드리지 않습니다. 비사업용자동차(건설기계 포함)가 파손 또는 오손되어 가동하지 못하는 기간 동안에 동급(또는 동일한 규모)의 렌터카를 사용하실 경우 대차료라는 항목으로 지급해 드리며 지급기준은 다음과 같습니다. * 인정금액 가. 렌터카를 사용하는 경우 : 대여자동차 통상의 요금 나. 렌터카를 사용하지 않는 경우 : 대여자동차 통상의 요금 35% 상당액 (2020년 11월 09일 이전 보험계약(책임개시)건의 사고의 경우 30% 상당액) * 인정기간 가. 수리가능한 경우 : 수리를 위해 자동차정비업체에게 인도하여 수리가 완료될 떄까지 소요된 기간으로 하되 25일(실제 정비작업시간이 160시간을 초과하는 경우 30일)을 한도로 함. 다만 부당한 수리지연이나 출고지연 등의 사유로 통상의 수리기간을 초과하는 기간은 인정하지 않음. 나. 수리 불가능한 경우 : 10일', 'AXA'),
('사고접수·보상', '보험처리를 할 때 보험회사에 사고를 접수하는 시기 및 통보사항은 무엇입니까?', '사고발생에 대한 통보 기한은 특별히 정한 것은 없지만 가능한 신속히 통보하는 것이 보상 직원으로부터 사고처리 과정에 대한 조언도 얻을 수 있을 뿐만 아니라 정확하지 않은 사고 규명으로 인한 불이익을 받는 것도 방지할 수 있기 때문에 가능한 한 즉시 사고 통보를 해주셔야만 합니다. 사고접수를 하실 경우에는 다음의 사항을 사고접수요원의 안내에 따라 답변해 주시면 됩니다. ■ 사고차량번호 ■ 사고일시 및 장소 ■ 운전자 및 운전자의 인적사항 ■ 사고내용 ■ 피해사항 즉 다친 사람 및 치료병원 파손된 차량 및 정비공장', 'AXA'),
('사고접수·보상', '형사합의금 혹은 공탁금은 이후 보험회사의 합의금에서 공제됩니까?', '형사합의금이나 공탁금이 전체적인 손해배상금의 일부로 간주되면 공제될 수도 있습니다. 따라서 공탁금을 찾아올 때 위로금 혹은 위로금의 일부 등으로 명시한 후 찾아오는 것이 유익합니다. 법원의 확정판결을 받는 경우에는 위로금이라고 명시하여도 법률상 손해배상금으로 보아 공제하는 경우도 있습니다.', 'AXA'),
('사고접수·보상', '도난당한 차에 의해 사고가 났습니다.', '도난차량에 있어서 관리상의 과실이 전혀 없고 도난 후에 차량에 대해서 운행지배나 운행이익이 완전히 상실되었다면 도난 중 사고에 대해서는 배상책임이 발생하지 않습니다. 그러나 일부의 제한적인 부분 외에는 차주가 차량을 소유. 사용. 관리상 과실이 인정되어 도난 기간 중의 사고에 대한 책임을 면하기 매우 어려움으로 차량의 소유자는 특별한 사정이 없는 한 주차 가능한 지역에 차량을 주차시키고 관리에 만전을 기해야 손해를 미연에 방지할 수 있습니다.', 'AXA'),
('사고접수·보상', '보장사업으로 보상을 받기 위해서는 피해자가 경찰서에 신고해야 합니까?', '보장사업으로 보상을 받기 위해서는 반드시 피해자가 관할 경찰서에 신고를 하여야 합니다. 그 이유는 가해차량이 검거될 경우 피해자가 가해자 또는 그 차량의 소유자로부터 손해배상을 받아야 하기 때문이며 또한 보장 사업은 정부가 사업주체이므로 국가기관으로부터 손해배상사실을 입증 받는 것이 합리적이기 때문입니다.', 'AXA'),
('사고접수·보상', '도로 틈에 고인 빗물이 튀어 시야가 방해되어 사고가 났습니다.', '도로의 홈이나 웅덩이를 제때 보수하지 않아 안전운행에 방해를 준 사실이 인정되므로 도로 관리청에 일정 부분 부분과실이 인정됩니다.', 'AXA'),
('사고접수·보상', '경찰서에서는 과실이 없다고 하는데 상대방 보험회사는 과실이 있다고 합니다.', '경찰서에서는 형사적 판단을 하고 보험회사에서는 민사적 판단을 하기 때문에 이와 같은 사례가 발생할 수 있습니다. 구체적으로 설명하면 경찰서 사고조사에서는 잘못이 좀더 많은 쪽이 가해자이고 적은 쪽이 피해자로 판단하게 되며 과실 비율을 정하거나 판단하지는 않습니다. 그러나 보험 회사에서는 민사적 측면의 공평한 손해배상을 위하여 가해자와 피해차량 운전자(또는 피해자)의 진술과 경찰서 조사 기록 및 현장조사를 통하여 사고당시 상황을 감안한 후 약관에서 정한 과실비율 인정기준의 과실도표를 적용해서 과실비율을 정하게 됩니다. 상대방 보험회사 직원의 과실판단이 이해가 가지 않는 경우에는 가입한 보험회사에 통보하여 보험회사 직원끼리 협의토록 하는 것이 좋습니다.', 'AXA'),
('사고접수·보상', '과실이 많은 피해자가 치료를 오래하면 불리합니까?', '과실이 있으면 모든 보상금에서 과실만큼 금액이 공제됩니다. 이 경우에는 치료비도 일단은 보험회사에서 전액 병원측에 지급하나 이후 보상금 산정시 치료비의 과실비율 해당액 만큼 보상금에서 공제하게 됩니다. 2023년 1월 1일부터 시행된 제도인 치료비 과실책임주의는 자동차 사고 경상 환자(상해등급 12~14급)의 치료비 중 본인과실 비율만큼을 본인이 부담하도록 한 것입니다. 이는 보험료 상승과 과잉 진료를 억제하기 위한 조치입니다. 1. 적용 대상 ∙ 차량 운전자(자전거 보행자 오토바이 제외) ∙ 상해등급 12~14급(경상 환자)에 해당 2. 부담 방식 ∙ 대인배상1(책임보험) 한도를 초과하는 치료비에 대해 본인 과실 비율만큼 부담 3. 부담 방법 ∙ 자비 납부 자동차상해 또는 자기신체사고보험으로 처리 가능 ∙ 보험 미가입 시 직접 부담', 'AXA'),
('사고접수·보상', '매매한 차를 명의이전 전에 매수인이 사고를 냈습니다.', '이 경우에는 사고차량에 대하여 매도인이 운행지배권이 있느냐 없느냐의 여부에 따라 책임이 결정됩니다. 만약 매매대금이 아직 완전히 결재 되지 않았고 이전등록 서류도 교부되지 않았다면 매도인은 언제든지 매도된 차량을 되돌려 받을 수도 있으므로 운행지배를 완전히 벗어났다고 할 수 없습니다. 따라서. 매도인은 책임을 면할 수 없습니다. 그러나 자동차 매매대금을 전액 지급 받고 이전등록에 필요한 서류와 차량을 인도한 상태에서 사고를 일으킨 경우에는 아직 매도인 명의로 등록되어 있다하더라도 매수인의 사정으로 이전등록을 못한 것이고 이 경우 매도인은 사고차량의 운행에 아무런 지배권도 없으므로 매수인이 발생시킨 사고에 대한 책임을 지지 않게 됩니다.', 'AXA'),
('사고접수·보상', '일반병실에서 상급병실(1~4인용)로 옮기려고 합니다.', '자동차보험 환자의 경우. 해당병원의 대중적인 일반병실을 기준으로 입원료를 지급하도록 되어있습니다. 피해자가 불편하여 상급병실을 사용하고자 한다면 대중적인 일반병실과의 병실료차액을 본인이 부담하여야 하지만 병원측의 병실사정으로 부득이하게 상급병실을 이용해야 하는 경우에는 7일 이내의 한도로 보험처리합니다.', 'AXA'),
('사고접수·보상', '타인을 동승 중 무보험차에 의해 사고가 났습니다.', '과실이 없어도 타인의 치료비 등을 물어줄 책임이 있습니다. 현행 자동차손해배상보장법(이하 자배법) 제3조에 의하면 “자기를 위하여 자동차를 운행한 자는 그 운행으로 말미암아 다른 사람이 사상했을 때에는 손해배상 책임을 진다.”라고 되어 있습니다. 특히 자동차 승객이 사상한 때는 그 승객이 고의 또는 자살로 인해 사상했다는 사실을 운전한 사람이 입증하지 못하면 손해배상책임을 집니다. 즉 현행 민법이 불법행위에 대해 과실책임을 묻는데 반해 교통사고 특히 인사사고에 해당하는 지배법에서는 (조건부)무과실 책임주의를 취하고 있습니다. 위의 경우에서 본인은 자기를 위해 차를 운전한 운행자이자 위험원인 자동차의 운행을 실질적으로 지배한 사람이므로 사고에 과실이 없다 하더라도 타인를 동승한 이상 손해를 배상할 책임이 있습니다.', 'AXA'),
('사고접수·보상', '공탁이란 무엇입니까?', '형사처벌을 받게 되는 가해자가 피해자와 형사합의를 하려하나 합의금의 대소 혹은 기타 다른 사정으로 인해 합의하지 못하는 경우 금전으로 법원에 공탁함으로써 가해자의 형사합의 의사를 재판부에 반영케 하려는 취지로 이루어지는것입니다. 재판부에서는 사고의 내용과 피해정도 종합보험가입여부 가해자의 재정적상태 등을 종합적으로 고려하여 공탁금의 적정성을 판단한 후 가해자에 대한 형사적인 처벌에 반영하게 됩니다. 그러나 이는 본질적으로 ‘형사합의’는 아닙니다. 다만 공탁액이 적절하다고 판단되는 경우엔 실제 형사합의가 된 것과 같은 참작효과가 있습니다.', 'AXA'),
('사고접수·보상', '무보험자동차에 의해 사고를 당해 차가 부서진 경우 무보험차상해로 보상이 가능한가요?', '무보험자동차 상해는 상해(인적사고)만 보상되므로 피보험자가 부상을 당하거나 사망을 하였을 경우에만 보상처리가 되므로 물적 손해에 대해서는 보상되지 않습니다. 만약 자기차량손해(자차)담보에 가입이 되어 있으시다면 당연히 보상 받으실 수 있습니다.', 'AXA'),
('사고접수·보상', '[상해] 의료비 비례보상은 왜 해야하나요?', '보험이란 다수의 경제주체가 우연한 위험에 대하여 적은 보험료를 납입하고 보험사고 발생시 큰 보험금을 지급받음으로써 보험계약자(피보험자)가 가지는 경제적 위험을 감경 제거하는 사회.경제제도입니다. 경제적 위험을 원상복구하여 위험으로부터 경제적 안정회복하는데 보험의 의의가 있으며 보험사고로 인하여 이익을 획득하는 제도는 아닙니다. 손해보험에서는 이를 이득금지원칙이라하여 손해보상의 대원칙으로 삼고 있습니다. 의료비의 비례보상도 이득금지원칙의 적용으로 동일한 의료비를 보상하는 다수의 보험계약이 체결되어 있는 경우(손해보험의 종합 장기손해 개인연금 퇴직보험 여행보험 골프보험 등) 의료비를 중복하여 지급하는 것이 아니라 의료비를 각각 안분하여 지급합니다.', 'AXA'),
('사고접수·보상', '치료비는 어떤 범위까지 인정이 됩니까?', '의사의 진단에 따라 의학적으로 인정되는 범위 안에서 보편 타당한 방법 범위 및 기술 등에 따라 행하여진 치료에 소요되는 비용을 지급합니다. 이때 외국에서 치료를 받은 경우에는 국내의료기관에서의 치료에 소요되는 비용 상당액 국내기관에서 치료가 불가능하여 외국에서 치료를 받은 경우에는 그에 소요되는 타당한 비용을 지급합니다.', 'AXA'),
('사고접수·보상', '신차가 사고가 나서 수리는 가능하나 다른 신차로 교환하려고 합니다.', '차량이 출고된지 얼마되지 않았다 하더라도 수리가 가능한 경우에는 새차로 교환해주지 않으며 수리비용이 차량가액을 초과 하거나 수리가 불가능한 경우에 한해 약정에 따라 사고당시 차량가액 전부를 지급합니다.', 'AXA'),
('사고접수·보상', '보험회사에서 정하는 과실비율은 절대적인 것입니까?', '보험회사에서 정하는 과실비율은 과실인정기준도표에 의하여 정합니다. 과실인정기준표는 그동안의 판례나 현행법령을 기초로 작성된 것으로 객관성을 인정받습니다. 보험회사간의 과실다툼이 있는경우 제3의 기관인 과실비율분쟁 심의위원회 소송 확정 판결로서 과실비율이 확정됩니다.', 'AXA'),
('사고접수·보상', '교통사고 가해자에겐 어떤 책임이 있습니까?', '교통사고가 발생하면 가해자에게는 다음과 같은 형사상 책임. 민사상 책임. 행정적 책임. 도의적 책임이 따릅니다. ■ 형사상의 책임 징역. 금고. 벌금. 과태료 등의 처벌이 있으며 14일간의 유예기간내의 합의 여부에 따라 책임을 추궁합니다. 또한 12대 중과실 사망 뺑소니 사고 또는 종합보험 미가입시에는 형사상 책임을 본인이 져야 합니다. ■ 민사상 책임 고의 또는 과실로 인한 위법행위로 타인에게 가한 손해배상 책임 ※ 자동차보험에서 보상하는 것은 “민사상책임”에 한정됩니다. ■ 행정적 처분 사고원인 및 결과에 따라 범칙금/벌점제에 의한 행정처분 및 제제 ■ 도의적 책임 피해자 및 그 가족에 대해 사죄의 뜻을 표하는 것을 말합니다', 'AXA'),
('사고접수·보상', '피해자에게도 과실이 있는 경우가 있습니까?', '교통사고가 발생하면 사고를 일으킨 가해자는 물론 피해자(보행인)에게도 스스로 자기자신의 안전을 위해서 주의를 기울여야 할 의무가 있다고 봅니다. 따라서 이러한 주의의무를 게을리한 잘못이 경합되어 사고가 발생하였다면 발생된 손해에 대해서도 피해자의 잘못만큼 보험금을 공제하게 되는데 이것은 손해배상의 공평한 분담이라는 특면에서 타당하기 때문입니다. 과실상계비율산정은. 사고당시의 상황을 종합적으로 판단하여 적용하게 되며 사고유형별로 기본과실을 우선 산정한 후 사고장소. 사고시간. 피해자의 형태.가해자의 과실정도에 따라 감산하게 됩니다.', 'AXA'),
('사고접수·보상', '사고난 차량이 제대로 수리가 되지 않았습니다.', '수리되어 출고된 차량에 이상이 있는 경우에는 원인에 따라 달라집니다. 정비공장과 논란의 여지가 있을 수는 있지만 단순히 수리공장의 명백한 잘못으로 차량에 이상이 생긴 경우에는 수리한 정비공장에서 재수리를 받으실 수 있습니다. 이 경우에는 수리공장에서 재수리를 해 주는 부분으로. 보험회사에서 추가적으로 수리비를 지급하는 것은 아닙니다. 현행 소비자 보호법에서는 정비공장은 3개월간 수리에 대한 보증을 의무로 규정하고 있습니다. 또한 사고로 파손된 부분을 수리공장에서 미처 발견하지 못하고 수리하지 않은 것이 원인이 되는 경우에는 수리는 받으실 있으며. 이 경우에는 보험회사에서 추가적으로 보험금을 지급하게 됩니다. 만약 수리 후 차량에 하자가 발생했다면 보험회사 담당직원에게 연락하여 협조를 받는 것이 좋습니다.', 'AXA'),
('사고접수·보상', '사고 후 집에 연락하기 위해 자리를 떴을 때에도 뺑소니에 해당합니까?', '만약 피해자에 대한 구호조치 없이 현장을 이탈했다면 뺑소니에 해당됩니다. 따라서 반드시 피해자에 대한 구호조치가 선행되어야 합니다.', 'AXA'),
('사고접수·보상', '12대 중과실사고인데도 가해자가 형사합의를 요청하지 않는 경우 어떻게 합니까?', '형사합의는 사고 가해자가 사고 발생으로 인한 형사 처벌을 완화하기 위해 취하는 방법입니다. 그러나 반드시 형사합의를 하도록 규정된 사항이 아니며 가해자가 원치 않는다면 피해자측에서 먼저 요구할 수는 없습니다. 가해자가 형사합의를 요청할 경우에는 적정한 금액으로 합의에 응하는 것이 좋습니다. 왜냐하면 형사합의는 가해자의 의무사항이 아니며. 피해자로서는 가해자를 무겁게 처벌하는 것보다 물질적인 보상을 받는 것이 유리하기 때문입니다.', 'AXA'),
('사고접수·보상', '사고로 옷이나 핸드폰 등의 소지품이 파손되었습니다.', '약관상"다른 사람의 서화 골동품 조각물 그 밖에 미술품과 탑승자와 통행인의 의류나 휴대품에 생긴 손해는 보상하지 않는다."라고 규정하고 있으며 "탑승자와 통행인의 분실 또는 도난으로 인한 소지품에 생긴 손해는 보상하지 않는다. 그러나 훼손된 소지품에 한하여 피해자 1인당 200만원의 한도로 실제 손해를 보상합니다." 라고 규정하고 있습니다. 약관 규정에 따라 의류는 보상되지 않으나 핸드폰은 소지품에 해당하여 훼손된 경우에 한하여 피해자 1인당 200만원의 한도로 실제 손해에 대하여 보상됩니다.', 'AXA'),
('사고접수·보상', '보험처리 중인데도 피해자가 금전적인 보상을 요구합니다.어떻게 해야되나요?', '도주사고 사망사고 및 12대 중과실사고를 제외한 일반사고의 경우는 종합보험 대인무한배상에 가입되어 있다면 별도로 피해자에게 금전적 배상은 하실 필요가 없습니다. 교통사고처리특례법에 의하면 교통사고로 형사적책임이 발생하였다고 하더라도 종합보험 대인배상을 무한보험에 가입되어 있다면 사망사고 도주사고 및 12대 중과실사고를 제외한 일반사고일 경우에 종합보험 가입사실증명원을 경찰관서에 제출하면 형사처벌을 면하게 됩니다. 또한 민사적 책임은 보험사에서 대행처리하므로 일반사고일 경우에는 보험계약자께서 피해자에게 별도로 개별보상을 하지 않으셔도 됩니다.', 'AXA'),
('사고접수·보상', '사고 난 차를 먼저 수리한 후 보험금을 청구할 수 있습니까?', '자동차 종합보험 약관에 보면 사고발생시 고객분들이 제출하여야 할 서류는 크게 보험금 청구서류와 손해액을 증명하는 서류 손해배상의 이행사실을 증명하는 서류 등 여러 가지가 있습니다. 중요한 것은 먼저 수리하였다고 보상이 안되는 것이 아니라 사고 당시 정확한 손해액에 대하여 보험사에서 산정할 수 있는 입증자료를 제시하시면 보상은 가능합니다.(최소한 수리 전 차량의 파손상태를 확인할 수 있는 파손상태라든가 견적서 또는 수리비 입금내용 등 확인) 이 경우라고 하더라도 보험회사의 보상기준에 합당한 보상기준에 의한 금액만 지급이 될 수 있으므로 부당요금이나 바가지 요금에 대한 차액을 부득이하게 손해를 보실 수 도 있습니다.', '하나손해보험'),
('사고접수·보상', '차를 바꿨으나 보험회사에 통보하지 않은 상태에서 사고가 났습니다.', '보험기간중 차량을 대체한 경우에는 그 사실을 보험회사에 알리고 보험회사의 승인을 받아야만 보험계약이 대체한 신차량에 승계가 되며 이러한 보험계약이 승계 없이 대체된 신차량이 야기한 사고에 대해서는 보험처리가 되지 않습니다.', 'AXA'),
('사고접수·보상', '보험처리를 하지 않고 개인적으로 합의할 때 유의할 사항은 무엇입니까?', '비교적 교통사고가 경미하여 보험처리를 하지 않고 가해자가 개인적으로 처리하는 경우에는 피해자의 성향에 따라서 후일 보상과 관련하여 종종 문제가 발생하기 때문에 이러한 문제를 사전 방지히기 위해서는 합의시 제3자 입회하여 피해자와 서면으로 합의서를 작성해 두는 것이 바람직 합니다. 합의서의 양식은 꼭 정해진 것은 없으며 자필로 작성하여도 무방하고 육하 원칙에 따라 가.피해자간의 인적사항 사고일시 및 장소 사고관련 차량번호 합의내용(합의금액 등)등이 포함되어야 하며 특히 합의로 피해자가번 사고에 대한 일체의 권리를 포기하고 민 형사상 이의를 제기하지 않겠다는 청구권 포기 문구를 기록하는 것이 후일 발생할 수 있는 문제를 예방 할 수 있습니다.', 'AXA'),
('사고접수·보상', '납입최고 기간중에 발생한 사고에 대해서도 보상이 가능합니까?', '보험료 분할납입 특약의 경우 약정한 납입일자까지 제2회 이후의 보험료를 납입하지 아니하는 때에는 약정한 납입일자로부터 30일간의 납입최고기간을 두는데 이 납입최고기간안에 발생한 사고에 대해서는 보상합니다. 그러나 납입최고기간의 마지막날 24 : 00 이후부터는 보상처리가 불가능합니다.', 'AXA'),
('사고접수·보상', '사고에 따른 손해배상청구권의 소멸시효 기간은 언제입니까?', '민법 제 766조(손해배상청구권의 소멸시효)에서는 불법행위로 인한 손해배상 청구권은 피해자나 그 법정대리인이 그 손해 및 가해자를 안 날로부터 3년간 행사하지 아니하고 경과하면 손해배상금을 지급받을 수 없게 되므로 유의하여야 합니다.', 'AXA'),
('사고접수·보상', '자기차량손해의 보상과 대물배상의 보상은 어떻게 다릅니까?', '자기차량손해 보상 및 대물배상 보상이 조금 상이합니다. 자기차량손해보상은 피보험자동차에 직접적으로 생긴 손해를 보험가입금액 한도로 보상하게 됩니다. 그러나 대물보상기준은 원상회복에 필요한 수리비를 지급하거나 전손일 경우에는 사고직전 패해물의 가액 상당액과 사고 직전 피해물의 가액에 상당하는 동종의 대용품을 취득할 때 실제로 소요된 필요타당한 비용을 지급합니다. 따라서 피해자의 경우 대물보상액이 자차가액에 미달하는 경우 손해를 최소화할 수 있는 방법은 피해자가 가지고 있는 대물손해배상 청구권을 피해자가 가입한 보험사에 위임하고 피해자가 가입한 차량보험으로 보험금을 청구하면 사고직전 차량가액으로 보상을 받으실 수가 있습니다. 다만 피해자가 과실이 있는 경우에는 갱신계약시 보험료가 할증됨을 유념하시기 바랍니다.', 'AXA'),
('사고접수·보상', '차량수리 후에 차량시세가 하락한 경우 보상이 되는지?', '출고된지 5년이하의 대물 피해차량이 사고로 인한 자동차의 수리비가 사고직전 차량가액의 20%를 초과하는 경우 1)출고 후 1년 이하인 자동차는 수리비용의 20% 2)출고 후 1년초과 2년이하인 자동차는 수리비용의 15% 3)출고 후 2년초과 5년이하인 자동차는 수리비용의 10%를 지급합니다.', 'AXA'),
('사고접수·보상', '가해자가 보험사에 접수를 안하는데 제가 가해자 보험사에 보상을 청구해도 되나요?', '원래 보험금 청구권은 피보험자에게 있으나 자동차보험 대인사고에서는 손해배상 청구권자인 피해자가 보험회사에 직접 청구할 수 있습니다. 먼저 경찰서에 사고신고를 하여 "교통사고 사실확인원"을 발급받으시고 진단서 등 피해상황을 첨부하여 보험사에 청구하시면 됩니다.', 'AXA'),
('사고접수·보상', '피해자가 괜찮다고 하여 그냥 돌아가라고 하는데 어떻게 해야 합니까?', '이런 경우에도 반드시 피해자에게 자신의 연락처를 남겨 두고 주변의 증인 등을 미리 확보하여 두는 것이 좋습니다.물론 피해자가 구호를 거부한 경우 피해자의 의사에 반하여 병원까지 우송해야 할 의무는 없다고 생각합니다만 당시 피해자가 상해를 입었음을 알고도 인명구호가 없이 그냥 갔다면 명백히 도주가 성립됩니다. 도주인지 아닌지는 사망 또는 상해사실을 알고도 또는 정확히 모르지만 다쳤을 수도 있다고 생각되는 미필적 고의도 포함해서 사고발생 시 구호조치 없이 현장을 이탈한 경우냐 아니냐로 판단하기 때문입니다. 특히 연락처조차 남기지 못한 채 그냥 헤어진 경우라면 반드시 해당 사고지역의 경찰서에 이러한 사실을 미리 신고하여 두면 만약의 뺑소니 혐의에서 벗어 날 수 있습니다.', 'AXA'),
('사고접수·보상', '사고가 발생하였을 때 어떤 조치들을 취해야 합니까?', '자동차 사고가 발생하면 즉시 정차하여 피해자 또는 피해차량의 상황을 확인하고 무엇보다도 우선하여 피해자에 대한 구호조치를 취하여야 합니다.피해자 구호조치라 함은 부상자를 구출한다든지 현장에서 응급조치를 하거나 또는 병원에 후송하는 행위 등이 구호조치에 해당되며 만일 이러한 피해자 구호조치를 소홀히하고 사고현장에서 이탈한 경우 뺑소니사고로 처리되어 특정범죄가중처벌등에 관한 법률 위반으로 엄한 처벌을 받게 됩니다. 구호조치가 끝난 후에는 관할 지구대 경찰서 등에 신고(물적 피해만 발생한 사고는 경찰서 신고의무가 없음)하고 보험회사에 사고사실을 통보하시면 됩니다.', 'AXA'),
('사고접수·보상', '음주운전 차량에 동승한 사람에게도 과실이 있는지?', '동승자의 경우에도 운전자로 하여금 안전하게 운전하도록 촉구할 주의의무가 있다고 보는 것이 법원의 한결 같은 판결입니다. 특히 음주운전의 경우 동승자는 운전자의 음주운전을 적극적으로 만류하여야 할 주의의무가 있음에도 음주운전의 사실을 알면서도 동승한 경우에는 그로 인해 동승자의 과실이 상당부분인정되며 경우에 따라서는 가중될 수 있습니다.', 'AXA'),
('사고접수·보상', '음주상태에서 사고발생시 보상받을 수 있나요?', '음주사고시 자기차량손해를 제외한 나머지 대인배상I II 대물배상 자기신체사고 무보험상해사고는 보상받으실 수 있습니다. 단 대인배상Ⅰ Ⅱ 대물 보상시 사고 부담금을 보험회사에 납부하셔야 합니다. 사고부담금은 아래 내용과 같습니다. ■ 대인배상Ⅰ : 전액(대인배상Ⅰ 한도내 지급보험금) ■ 대인배상Ⅱ : 1사고당 1억원 ■ 책임대물 : 전액(지급보험금) ■ 임의대물 : 1사고당 5 000만원', 'AXA'),
('사고접수·보상', '사망보험금 수익자는 어떻게 되나요?', '보험기간 중 사고 발생 전까지는 보험계약자는 보험금 수익자를 별도로 지정할 수 있습니다. 별도의 보험금 수익자를 지정하지 않으신 경우에는 민법의 상속관련 규정에 따라 법정상속인에게 보험금을 안분하여 지급합니다.이 경우 각 상속인이 지급받는 대신 1명의 대표자가 보험금을 수령하셔야 하는 경우에는 보험금을 위임하시는 분과 위임받는 분께서 보험금위임장을 작성 및 인감 날인 후 인감증명서와 함께 제출하시면 대표수익자에게 보험금 지급이 가능합니다.', 'AXA'),
('사고접수·보상', '개인(신용)정보 활용에 동의해야 하나요?', '보험회사가 손해사정 및 사고조사 보험금지급심사 등의 업무를 수행하기 위해 「신용정보의 이용 및 보호에 관한 법률」 「개인정보보호법」 등에 따른 개인정보처리 동의가 반드시 필요합니다. 개인정보처리동의서 또는 의료 심사 등에 동의 거부 시 보험급 지급이 지연되거나 불가할 수 있습니다.', 'AXA'),
('사고접수·보상', '보험금 지급심사 진행상황을 확인할 수 있나요?', '보험회사 인터넷 홈페이지 또는 모바일 페이지 및 콜센터를 통해 지급심사 진행과정 및 처리결과를 조회하실 수 있습니다.', 'AXA'),
('사고접수·보상', '현재 보험회사에서 조사 중 이라고 합니다. 보험금을 미리 받을 수 있을까요?', '보험금을 지급하지 못할 것으로 예상되는 경우에 회사가 추정하는 보험금의 50%이내에서 보험금을 지급할 수 있습니다.(=가지급보험금)단 최종 결정 보험금이 없거나 가지급보험금보다 작으면 지급된 보험금은 환수됩니다.', 'AXA'),
('사고접수·보상', '보험금 청구서류 접수 후 언제 보험금을 받을 수 있나요?', '예상지급일은 최종 서류접수일로 부터 3영업일 지급사유 조사나 확인이 필요한 경우 30영업일 이내입니다.지급기일 내에 지급하지 못 할 경우 지연사유 지급예정일을 안내해 드리며 지급예정일을 초과하는 경우 약관에 따라 지연이자를 산정하여 드립니다. 또한 지급심사 결과 지급거절 될 수 있으며 이 경우 지급거절 사유를 안내해드립니다.지급거절 결정에 동의 하시지 않는 경우 소비자보호팀으로 통보하시면 재심사를 받으실 수 있습니다.', 'AXA'),
('사고접수·보상', '실손의료보험에 중복가입한 경우 보험금은 어떻게 지급 되나요?', '실손의료보험에 중복가입 된 경우 보험금은 비례보상 원칙에 따라 계약별로 비례하여 지급됩니다.', 'AXA'),
('사고접수·보상', '중복가입한 경우 보험금 청구서류를 회사마다 각각 제출해야 하나요?', '아닙니다. 실손의료보험에 중복가입한 경우 최초 보험금 청구서류를 받은 보험회사에서 다른 보험회사로 이를 전달하는 「보험금 청구서류 접수대행서비스」를 시행 중입니다. 해당 서비스 이용을 원하는 경우 서비스 이용 신청서를 작성하시어 청구서류와 함께 보험회사로 제출하여 주시기 바랍니다.(단 각 보험회사 특약에 따라 별도 제출서류가 있을 수 있습니다.)', 'AXA'),
('사고접수·보상', '손해사정사를 선임하려고 합니다. 제가 비용을 부담해야 하나요?', '* 보험계약자등 부담 - 보험회사가 고용선임한 손해사정사가 사정한 결과에 보험계약자 등이 승복하지 않을 때 - 보험계약자 등이 보험회사와 별도로 손해사정사를 선임하고자 할 때 * 보험회사 부담 - 손해사정 전에 보험계약자 등이 보험회사에게 손해사정의 선임의사 통보하여 동의 받은 때 - 정당한 사유 없이 보험회사가 보험사고 통보를 받은 날로 부터 7일이 경과해도 손해사정을 착수하지 않을 때', 'AXA'),
('사고접수·보상', '손해사정사 선임시 무엇을 유의해야 하나요?', '선임 시 비용이 발생할 수 있으며 선임한 독립손해사정사는 보험금의 대리청구 보험회사와 보험금에 대하여 합의 또는 절충 등의 불공정 행위를 할 수 없습니다.', 'AXA'),
('사고접수·보상', '보험금 지급사유에 대하여 보험회사와 합의하지 못한 경우 다시 의료심사를 받을 수 있을까요?', '보험수익자와 보험회사가 지급사유에 합의하지 못 할때 보험수익자와 보험회사가 함께 제3자를 정하고 그 제3자의 의견을 따를 수 있습니다. 제3자는 종합병원 소속 전문의로 하며 지급사유 판정에 드는 비용은 보험회사가 부담합니다.', 'AXA'),
('사고접수·보상', '손해사정서를 확인할 수 있나요?', '보험금 청구권자가 요청하는 경우 보험회사는 손해사정사가 작성·제출한 손해사정서를 열람하게 하거나 그 사본을 교부하여 드립니다.', 'AXA'),
('사고접수·보상', '손해사정사 및 손해사정업자의 등록여부는 어떻게 확인이 가능한가요?', '금감원 홈페이지(www.fss.or.kr) 메뉴의 업무자료>보험업무>보험전문인(업)/보험중개사> 금융감독원 등록여부 조회시스템에서 검색하시면 됩니다.', 'AXA'),
('사고접수·보상', '보험금 청구를 했더니 제 3의 의료기관에서 의료자문을 받아야 한다고 해서 불편합니다. 어떻게 해야 하나요?', '보험금을 청구한 자와 회사가 보험금 지급사유에 대해 합의하지 못할 때는 양자가 함께 제3자를 정하고 그 제3자의 의견에 따라 손해액을 평가 및 확정하여야 원활한 보험금 지급절차가 가능합니다. 참고로 장해지급률의 판정 및 지급할 보험금의 결정과 관련하여 확정된 장해지급률에 따른 보험금을 초과한 부분에 대한 분쟁으로 보험금 지급이 늦어지는 경우에는 보험금 청구권자의 청구에 따라 이미 확정된 보험금을 먼저 가지급 받을 수 있습니다.', 'AXA'),
('사고접수·보상', '신용불량자가 되었어도 보험금을 수령하는 데는 문제가 없나요?', '민사집행법 시행령 제6조(압류금지 보장성 보험금 등의 범위)에 따라 사망보험금 중 1천만원 이하의 보험금 진료비 등 치료 및 장애회복을 위하여 실제 지출되는 비용을 보장하는 보험금 치료 및 장애회복을 위한 보험금 중 실비를 제외한 보험금의 1/2 등에 대해서 압류를 금지하고 있습니다. 다만 통장압류가 설정되어 있을 수 있으니 보험금 청구시 통장압류 여부를 해당 금융기관에 확인하시기 바랍니다.', 'AXA'),
('사고접수·보상', '기존 병실이 꽉 차 상급병실을 이용했을 경우에 보상 기준은 어떻게 되나요?', '입원 시 실제로 사용한 병실과 기준병실의 병실료 차액에서 50%를 뺀 금액을 지급합니다. 다만 1일 평균금액 10만원을 한도로 하며 1일 평균금액은 입원기간 동안 상급병실료 차액 전체를 총 입원일수로 나누어 산출합니다. 다만 보험가입 시기에 따라 보상기준이 상이할 수 있으므로 반드시 해당 약관을 확인하시기 바랍니다.', 'AXA'),
('사고접수·보상', '동시에 2종류 이상의 수술을 받으면 보험금도 2회 지급받을 수 있나요?', '하나의 사고로 두가지 이상의 수술을 받은 경우에는 하나의 수술비만 지급합니다.', 'AXA'),
('사고접수·보상', '다른 보험사에 실손이 중복되어 가입되어 있을 경우 보험금은 어떻게 지급되나요?', '각 보험계약에서 비례보상됩니다.', 'AXA'),
('사고접수·보상', '상해 입원 시 입원일수가 누적되어 보상되나요?', '동일한 상해의 치료를 목적으로 2회이상 입원한 경우 이를 1회 입원으로 보아 각 입원일수를 더합니다. 병원 또는 의원을 이전하여 입원한 경우에도 동일한 상해의 치료를 목적으로 입원한 경우에는 계속하여 입원한 것으로 보아 각 입원일수를 더합니다. 다만 보험가입 시기에 따라 보상기준이 상이할 수 있으므로 반드시 해당 약관을 확인하시기 바랍니다.', 'AXA'),
('사고접수·보상', '갑상선 암 진단을 받고 림프절 전이가 되었습니다. 전이암 보험금 지급 기준이 어떻게 되나요?', '원칙적으로 암의 원발부위(최초 발생한 부위)를 기준으로 분류하므로 갑상선이 최초 암 발생 부위라면 갑상선암진단금을 기준으로 지급하게 됩니다.', 'AXA'),
('사고접수·보상', '과거의 병이 현재 발병한 병과 인과관계가 있다며 보험금 지급을 거절하고 있습니다. 부당한 것 아닌가요?', '계약전 알릴의무 위반에 의한 계약의 해지가 보험금 지급사유 발생 후에 이루어진 경우에 회사는 보험금을 지급하지 않습니다. 다만 알릴의무를 위반한 사실이 보험금 지급사유 발생에 영향을 미치지 않았음을 계약자 피보험자 또는 보험수익자가 증명한 경우에는 약정한 보험금을 지급합니다.', 'AXA'),
('사고접수·보상', '보험금은 피보험자만 받을 수 있나요?', '1) 보험금의 청구 : 타인을 지정대리청구인으로 설정한 경우 또는 대리행위를 위임받은 경우는 피보험자를 대신하여 보험금 청구가 가능합니다. 2) 보험금의 지급 : 보험사고 발생 전 보험금수익자(생존 시·사망 시)를 지정해둔 경우에는 피보험자 이외 지정된 수익자가 보험금을 수령할 수 있습니다. 지정수익자가 없는 경우에는 보험금위임장을 작성하신 경우 지정수익자에게 보험금을 지급할 수 있습니다. 이 때 별도의 위임장 인감증명서 개인(신용)정보동의서 및 보험사가 필요로 하는 서류를 제출하여야 합니다.', 'AXA'),
('사고접수·보상', '미성년자의 경우 보험금 청구서는 누가 작성해야 하나요?', '미성년자 및 금치산자 한정치산자의 경우 그 친권자 또는 후견인이 작성하시면 됩니다. 부모가 공동친권자인 경우 다른 일방의 의사에 반하지 않는다면 부모 중 일방이 부모 공동명의로 서명할 수 있습니다.', 'AXA'),
('사고접수·보상', '보험금을 청구했더니 손해사정사가 조사를 나온다고 합니다. 보험사가 아닌 제3자가 조사를 하는게 정당한 절차인가요?', '보험회사는 보험업법 제185조 및 동법 시행령 제96조 2에 의거 손해액 평가 및 보험금의 손해사정에 관한 업무에 대해 손해사정사 또는 손해사정을 업으로 하는 자(손해사정업자)를 선임하여 그 업무를 위탁할 수 있습니다.', 'AXA'),
('사고접수·보상', '여러 보험사에 청구를 했는데 어떤 보험회사는 지급하고 어떤 보험회사는 지급을 하지 않습니다. 보험회사마다 다를 수가 있나요?', '보험금의 적정성을 심사하여 적정한 보험금이 지급되도록 하는 것이 중요하며 이 과정에서 보험회사마다 절차에 따른 진행 시간에 차이가 발생하는 경우가 있습니다.', 'AXA'),
('사고접수·보상', '보험 가입 전에 발병한 질병으로 사망한 경우 질병사망 보험금을 받을 수 있나요?', '약관상 보험가입 전 발병한 질병에 대해서는 보상하지 않음을 명시하고 있습니다.', 'AXA'),
('사고접수·보상', '갑작스런 사고로 인해 제왕절개를 해야 할 경우 보상이 가능한가요?', '질병∙상해 표준약관에는 피보험자의 임신 출산(제왕절개 포함) 유산(예 : 자궁외임신 계류유산 전치태반 태반의조기박리 등) 등으로 보험금 지급사유가 발생한 때에는 보험금을 지급하지 않는다고 명시되어 있습니다. 그러나 임신 출산 유산과 무관하게 발생한 상해나 질병은 보상 가능합니다.', 'AXA'),
('사고접수·보상', '진단서 발급비용도 보험처리가 가능할까요?', '진단서(입퇴원확인서 장해진단서 등)등의 보험금청구서류 발급비용은 보상되지 않습니다.', 'AXA'),
('사고접수·보상', '약관상 ''수술''은 무엇을 뜻하는건가요?', '수술이라 함은 병원 또는 의원의 의사의 자격을 가진 자에 의하여 질병 또는 상해로 인한 진단의 치료가 필요하다고 인정된 경우로서 자택 등에서의 치료가 곤란하여 의료법 제3조(의료기관) 제2항에 정한 국내의 병원 의원 또는 이와 동등하다고 회사가 인정하는 국외의 의료기관에서 의사의 관리하에 5대골절의 치료를 직접적인 목적으로 의료기구를 사용하여 생체에 절단(특정부위를 잘라내는 것) 절제(특정부위를 잘라 없애는 것) 등의 조작을 가하는 것(보건복지부 산하 신의료기술평가위원회(향후 제도변경시에는 동 위원회와 동일한 기능을 수행하는 기관)로부터 안전성과 치료효과를 인정받은 최신 수술기법도 포함됩니다)을 말하며 흡인(주사기 등으로 빨아들이는 것) 천자(바늘 또는 관을 꽂아 체액 조직을 뽑아내거나 약물을 주입하는 것) 등의 조치 및 신경 Block(신경의 차단)은 제외합니다.', 'AXA'),
('사고접수·보상', '암 진단비를 받으려면 의사의 소견이 있어야 하나요?', '암 진단 확정은 검사(조직검사 영상검사 등 암진단을 내리기 위한 검사)의 결과 판독일을 기준으로 하기 때문에 암 진단비를 청구하시려면 기본적으로 암확정진단서 조직검사 결과지가 필요하며 암의 특성에 따라 조직검사외 방법으로 진단을 내린 경우 담당자가 추가서류를 요청 할 수 있습니다.', 'AXA'),
('사고접수·보상', '건강검진비는 보상받을 수 있나요?', '건강검진비용은 실손의료보험에서 보상되지 않습니다 그러나 건강검진 이후에 이상 소견으로 인한 재검사 및 진찰등의 비용은 경우에는 보상가능합니다.', 'AXA'),
('사고접수·보상', '갑작스런 폭행을 당했을 경우 상해보험 보험금 청구가 가능한가요?', '기본적으로 폭력 폭행사고는 보상이 되지 않으나 정당방위로 인정되거나 일방적으로 맞은 피해자인 것이 서류로 입증될 경우 보상심사를 거쳐 보상받으실 수도 있습니다. 입증서류는 경찰서 신고를 한 경우 폭행사고 사건사실확인원이 필요하며 신고하지 않았다면 병원 초진진료차트나 진단서 등을 발급받으셔야 합니다.', 'AXA'),
('사고접수·보상', '상해사고의 개념은 무엇인가요?', '상해보험에서 담보되는 위험으로서 상해란 급격하고도 우연한 외래의 사고를 말합니다.', 'AXA'),
('사고접수·보상', '야외활동을 하다가 부상을 당했을 경우 보상을 받지 못하는 ''활동''에는 무엇이 있나요?', '보상하지 않는 사항은 다음과 같습니다. 1. 전문등반(전문적인 등산용구를 사용하여 암벽 또는 빙벽을 오르내리거나 특수한 기술 경험 사전훈련을 필요로 하는 등반을 말합니다) 글라이더 조종 스카이다이빙 스쿠버다이빙 행글라이딩 수상보트 패러글라이딩 2. 모터보트 자동차 또는 오토바이에 의한 경기 시범 흥행(이를 위한 연습을 포함합니다) 또는 시운전(다만 공용도로상에서 시운전을 하는 동안 보험금 지급사유가 발생한 경우에는 보장합니다) 3. 선박승무원 어부 사공 그밖에 선박에 탑승하는 것을 직무로 하는 사람이 직무상 선박에 탑승하고 있는 동안 이 외에도 보험가입 시 고지하지 않은 이륜차 사용으로 인한 사고 이륜차부담보특약가입된 계약에서의 이륜차사고 등은 보상되지 않을 수 있으니 참고하시기 바랍니다.', 'AXA'),
('사고접수·보상', '심신상실이란 어떤 상태를 뜻하나요?', '약관상 심신상실자라 함은 정신병 정신박약 심한 의식장애 등의 심신장애로 인하여 사물 변별 능력 또는 의사결정 능력이 없는 자를 말합니다. 즉 정신병 정신박약 심한 의식장애 등의 심신장애로 인하여 자신의 행위가 죽음으로 이어질 것을 정상적으로 판단할 수 없는 상태를 심신상실상태에 해당한다고 할 수 있습니다.', 'AXA'),
('사고접수·보상', '상해사고 여부에 대하여 분쟁이 있을 경우 보험사고의 입증책임은 누구에게 있나요?', '상해보험에서 담보되는 위험으로서 상해란 급격하고도 우연한 외래의 사고를 말하는 것으로 그 사고의 원인이 신체 외부로부터 작용한 것이라는 등의 사고의 외래성과 상해라는 결과와의 사이에 인과관계에 대한 입증은 보험금 청구자에게 있습니다(대법원2001. 8.21. 선고 2001다27579판결).', 'AXA'),
('사고접수·보상', '임신 출산은 보험금을 받지 못하나요? 자연유산도 보상하지 않는 사항에 해당하는건가요?', '질병∙상해 표준약관에는 피보험자의 임신 출산(제왕절개 포함) 유산(예 : 자궁외임신 계류유산 전치태반 태반의조기박리 등) 등으로 보험금 지급사유가 발생한 때에는 보험금을 지급하지 않는다고 명시되어 있습니다. 그러나 임신 출산 유산과 무관하게 발생한 상해나 질병은 보상 가능합니다.', 'AXA'),
('사고접수·보상', '선천성 질환은 보상받을 수 없나요? 설계사로부터 해당 설명을 듣지 못했습니다.', '약관상 지급 기준에 따라 차이가 있으나 대다수의 담보는 선천성질환에 대하여 보장하지 않고 있습니다.', 'AXA'),
('사고접수·보상', '이륜자동차 운전중 상해 부담보 특약에 가입하였는데 일회성으로 오토바이를 운전하였는데 운전중 사고가 났다면 보상이 불가한가요?', '보험증권에 기재된 피보험자가 보험기간 중에 직업 직무 또는 동호회 활동 등 주기적으로 이륜자동차를 운전(탑승을 포함합니다)하는 중 상해사고가 발생한 경우에 보험금을 지급하지 않습니다. 다만 1회성으로 이륜자동차를 운전(탑승)한 경우는 보상이 가능합니다.', 'AXA'),
('사고접수·보상', '자살 및 고의로 인한 사망은 보상받을 수 없나요?', '보험사고는 사고발생 여부 시기 방법 등의 우연성을 필요로 합니다. 따라서 자살 및 고의로 보험사고가 발생한 경우에는 그 사고에 우연성이 없으므로 상법 제659조에 따라 보험회사는 보험금지급책임을 면합니다. 약관상으로도 자살 및 고의사고는 면책으로 규정하고 있습니다. 다만 피보험자가 고의로 자신을 헤친 경우 심신상실 등으로 사고당시 피험자가 자유로운 의사결정을 할 수 없는 상태에서 자신을 해친 사실이 증명된 경우에는 사고이전 정신질환병력 등에 따라 재판단이 가능할 수 있으니 참고하시기 바랍니다.', 'AXA'),
('사고접수·보상', '피보험자가 갑자기 사망했는데 급성심근경색 진단비를 줄 수 없다고 합니다. 이게 맞나요?', '갑자기 사망한경우 부검을 시행하여 급성심근경색으로 부검결과가 나왔을 시 보상이 가능합니다. 그러나 부검도 없고 사망이전 약관상 급성심근경색진단비를 지급할만한 검사를 시행하지 않았을 경우에는 관련 증빙이 어려우므로 지급이 불가능합니다.', 'AXA'),
('사고접수·보상', '''부담보''란 무엇이며 보험기간 전체에 대해 부담보(보상하지 않음)로 가입이 된 경우 보험기간 내내 보상을 받지 못하는건가요?', '부담보란 보험기간 중 특정부위 및 특정질환에 대해서 일정기간 또는 전기간 질병으로 인한 수술이나 입원등의 각종 보장에서 제외하여 조건부로 가입하는 것을 말합니다. 이는 일반적으로 보험계약 청약시 피보험자가 병력에 대해 보험회사에 고지하고 보험회사에서는 해당 질병 및 부위에 대해 보장을 하지 않는 것으로 계약을 인수할 때 발생하게 됩니다. 전기간 부담보라 할 지라도 최초 계약일[또는 부활]로 부터 5년 이내에 부담보가 설정된 신체부위에 ""추가 진단을 받거나 치료사실이 없을경우""에 한하여 부담보 부위라도 보장이 가능합니다. 또한 부담보가 설정된 신체부위라 하더라도 상해로 인한 경우에는 보장이 가능합니다.', 'AXA'),
('사고접수·보상', '보험가입금액이란 무엇을 뜻하나요?', '보험가입금액이란 보험사고가 발생할 경우 보험자가 피보험자 또는 보험수익자에게 지급하기로 약정한 금액으로서 손해보험에서는 보험가액의 범위내에서 보험자가 지게 되는 보상책임의 최고한도액을 의미하고 인보험에서는 계약에서 정한 금액을 말합니다.', 'AXA'),
('사고접수·보상', '진단비는 가입금액 전액을 보상해 주나요?', '담보별 세부내용을 확인해야하며 약관상 공제부분을 제외하고는 전액 보장합니다. (ex. 약관상 1년미만 50% 1년이상 100% 암진단비경우 90일이내 진단 면책 소액암 진단시 소액암 지급률 별도 적용 등)', 'AXA'),
('사고접수·보상', '암보험을 여러 회사에 가입했으면 중복해서 보상받을 수 있을까요?', '암 진단비를 정액으로 보장받는 경우에는 중복보상이 가능합니다.', 'AXA'),
('사고접수·보상', '여러 직무를 수행하는 경우 상해급수는 어떻게 적용이 되나요?', '상해급수를 어떤 기준으로 적용하는 지는 사정변경에 따른 보험회사의 경영판단 사항으로 보험회사의 인수심사기준 등에 따라 결정되는 사항이며 보험회사의 인수심사기준이나 보험료 및 책임준비금 산출방법서 등에서 여러가지 직무를 수행하는 경우 가장 위험한 직무를 기준으로 상해급수를 정하도록 규정하고 있으므로 가장 위험한 직무를 기준으로 상해급수를 정하게 됩니다.', 'AXA'),
('사고접수·보상', '가정주부였지만 아르바이트 형식으로 잠시 일을 나가도 직업이 변경되었다고 고지해야 하나요?', '직업 또는 직무 변경 이륜차 등의 계속적 사용 시 지체없이 보험회사에 알려야 합니다. 아르바이트라 하더라도 일과성이 아니고 계속적으로 근무한다면 직업변경 통지를 하여야 합니다.', 'AXA'),
('사고접수·보상', '실손보험에서 자기부담금이란 무엇인가요?', '자기부담금이란 보험가입자에게 보험사고가 발생할 경우 보험가입자가 부담하게 되는 손해액의 일부를 말합니다.', 'AXA'),
('사고접수·보상', '퇴원시 처방조제를 받은 경우 100% 보상이 가능한가요?', '의사로부터 직접적 치료를 목적으로 처방받은 약제비에 대해 입원의료비로 지급가능하며 지급비율은 자기부담금의 비율에 따라 달라집니다.', 'AXA'),
('사고접수·보상', '해외에서 사고가 난 경우 보상받는 금액의 환율 기준은 어느시점을 기준으로 하나요?', '해외에서 사고가 발생하여 청구시 보험금 지급 시점의 환율 기준(전신환대고객매도율)에 따릅니다', 'AXA'),
('사고접수·보상', '입원 치료를 받고 있으면서 중간에 청구하면 중간정산한 비용을 받을 수 있나요?', '실손의료보험(실손의료비) 가입자중 입원 치료후 경제적인 사유로 의료비를 선납입하기가 곤란한 일정대상자에 한해 중간정산액 중 일부(예상 지급보험금의 70%)를 선지급하는 의료비 신속지급 제도의 서비스를 받을 수 있습니다. 최종 치료비 정산시 중간정산 비용과의 차이가 발생할 여지가 있는 관계로 중간 정산 후 청구시 청구금액의 일정 한도내에서 보험금 지급이 가능한 것입니다. 대상자는 ①의료급여법상 1종. 2종 수급권자 ② 본인일부부담금 산정 특례에 관한 기준에 정한 중증질환자 ③의료비 중간정산액(본인부담기준)이 300만원 이상인 고액의료비를 부담하는자 등입니다.', 'AXA'),
('사고접수·보상', '하루에 다른 질병으로 여러 곳에서 치료를 받았는데 통원의료비 자기부담금은 1일로 공제되나요?', '다른질병으로 치료를 목적으로 하루에 의료기관에 2회 이상 통원치료시(다른질병으로 약국을 통원 2회 이상의 처방조제를 포함)각각의 외래 및 처방으로 간주하여 각 의료기관(약국)별 자기부담금을 공제합니다. 참고로 동일한 질병은 발생원인이 동일한 질병이거나 질병 치료 중에 발생된 합병증 또는 새로 발견된 질병치료가 병행되거나 의학상 관련 없는 여러 종류의 질병을 갖고 있는 상태에서 입원하여 치료 받은 경우를 말하며 이 경우 동일한 질병으로 치료 받은 것으로 봅니다.', 'AXA'),
('사고접수·보상', '보험금은 사고일 또는 발병일로부터 언제까지 청구가 가능한가요?', '사고가 발생한 날 또는 사고를 안날로부터 3년 이내에 청구할 수 있습니다.', 'AXA'),
('사고접수·보상', '보험금 청구권 법적 소멸시효는 언제이며 법적 소멸시효가 끝나면 청구를 할 수가 없나요?', '상법 제 662조에 따라 보험금 청구권의 소멸시효는 3년이며 보험료 또는 적립금의 반환청구권은 3년간 보험료 청구권은 2년간 행사하지 않으면 소멸됩니다. 법적 소멸시효가 끝났을 경우라도 시효의 중단 등에 따라 달라질 수 있으므로 보험회사에 연락하여 상세한 상담을 통해 처리하여 주시기 바랍니다. *[보험금청구권 관련 참고사항] 상법 개정 시행(2015.03.12)에 따라 시행일 이후 체결되는 보험계약 및 시행일 이후 청구권이 발생하는 경우는 소멸시효가 3년 시행일 이전의 경우 소멸시효가 2년입니다.', 'AXA'),
('사고접수·보상', '실손의료비약관상 보상하지 않는 손해에 치핵(K64)은 명시되어 있지 않습니다. 그렇다면 질병코드 K64로 진단받은 치핵치료는 보험금 지급이 가능한가요?', '질병의료비 담보와 관련하여 기존약관에는 "직장 또는 항문질환 중 국민건강보험법상 요양급여에 해당하지 않은 부분(I84 K60~K62)"은 보상하지 않는 사항으로 규정되어 있었으나 WHO권고에 따라 한국표준질병사인분류(KCD) 제7차개정시 치핵 관련 질병코드가 I84에서 K64로 단순히 대체된 것에 불과하므로 기존약관에 K64코드가 없더라도 여전히 보상하지 않는 사항에 해당합니다.', 'AXA'),
('긴급출동·차량서비스', '긴급출동서비스 특별약관이란 무엇입니까?', 'XA자동차보험은 국내 최대의 현장출동 서비스망을 구축하고 있는 SK스피드메이트와 제휴하여 다양하고 신속한 서비스를 제공해 드리고 있습니다. 보험가입시 선택하여 가입하실 수 있으며 연간 5회 이용 가능합니다. 자세한 서비스 내용은 다음과 같습니다. ▲ 긴급견인서비스 ▲ 비상급유 서비스 ▲ 배터리 충전서비스 ▲ 예비타이어 교체 서비스 ▲ 잠금장치 해제서비스 ▲ 긴급구난 서비스 ▲ 타이어펑크 수리서비스 긴급출동서비스 확장(50Km)특별약관 (전기차 전용)긴급출동서비스 확장(150Km)특별약관으로 나눠져 있습니다.', 'AXA'),
('긴급출동·차량서비스', '긴급출동서비스는 어디서 해 주나요?', '긴급출동전문업체인 SK 스피드메이트와 업무제휴를 맺고 이들의 전국 650개 가맹점 중 고객이 계신 지점과 가장 가까운 가맹점에서 직접 출동하고 있어 전국 어디서든지 불편함 없이 서비스를 받으실 수 있습니다.', 'AXA'),
('긴급출동·차량서비스', '운행중 타이어가 빠지면서 사고가 났습니다.', '피해차량의 수리비는 대물배상으로 보상처리 가능하며 타이어가 빠진 자차는 타이어 부위만 제외하고 타이어가 빠짐으로 인한 추가 파손 부위가 있을 때는 자기차량으로 보상 받을 수 있습니다.', 'AXA'),
('긴급출동·차량서비스', '견인비의 지급기준은 어떻게 됩니까?', '자동차보험에서는 견인비를 피보험자동차가 제힘으로 움직일 수 없을 때에 이를 고칠 수 있는 가장 가까운 정비공장이나 회사가 지정하는 곳까지 운반하는데 든 비용을 말합니다. 또한 그곳까지 운반하는 데 든 임시수리비용 가운데 정당하다고 인정되는 부분은 수리비의 일부로 봅니다. 따라서 본인의 필요에 의해 추가되는 견인비는 인정되지 않습니다', 'AXA'),
('운전자보험', '에도 운전자 보험이 있나요?', '운전자보험이란 차량운전자를 위하여 교통상해위험(사망/후유장해)과 운전 중 발생하는 비용(자동차사고부상 벌금 운전중변호사선임비용 형사합의지원금 면허취소위로금 등)을 하나의 증권으로 보상하는 보험입니다. 자가운전시 사망후유장해 자동차사고부상 입원일당 형사합의지원금 벌금 운전중변호사선임비용 면허정지 및 취소 위로금을 보장해드립니다. 담보별 보장내용은 보험상품 - 운전자보험에서 확인하실 수 있습니다. ※ 직업에 따라서 보험료는 달라질 수 있습니다.', 'AXA'),
('운전자보험', '음주로 인하여 면허가 취소되었습니다. 면허취소위로금에 대해 보상이 가능합니까?', 'XA다이렉트 운전자보험은 면허취소위로금을 담보로 하고 있으나 음주 무면허 도주 약물 등에 대한 손해에 대해서는 보상하지 않습니다.', 'AXA'),
('운전자보험', '운전자보험 가입후 과속으로 인한 과태료가 부과되었을 경우 보상되나요?', 'XA다이렉트 운전자보험은 벌금을 보장하고 있으며 이는 피보험자 자동차를 운전 중 사고로 타인의 신체에 상해를 입힘으로써 확정판결에 의하여 정해진 벌금액을 1사고당 보험증권에 기재된 보험가입금액을 한도로 지급합니다. 단 타인의 신체에 대한 상해가 있어하며 타인의 재물을 손상시킨 경우는 해당되지 않습니다. 또한 법원의 확정판결에 따라 정해진 벌금액이 있어야 하므로 행정처분(과태료 범칙금 등)과는 그 성질이 다르므로 이는 보상되지 않습니다.', 'AXA'),
('고객지원·기타', '[상해]상해보험도 세금혜택이 있습니까?', '상해보험 및 다이렉트운전자보험을 가입하신 계약자가 근로자 연말정산시 보험료 납입증 명서를 제출하시면 100만원 한도내에서 소득공제혜택을 받으실 수 있습니다.', 'AXA'),
('고객지원·기타', '[상해]일반상해는 어떤 경우를 말합니까?', '급격하고 우연한 외래적인 사고로 신체에 상해를 입는 것을 말합니다. 즉 갑작스럽게 사고 원인이나 결과를 알 수 없는 우연한 외부의 힘에 의해 일어난 사고를 뜻합니다. 예를 들면 교통사고 추락사고 익사사고 화재사고 열차사고 비행기사고등 입니다.', 'AXA'),
('고객지원·기타', '보험수익자를 꼭 지정해야하나요?', '보험수익자를 지정하지 않을 경우에는 기명피보험자의 사망보험금 수령자는 법정상속인이 됩니다.따라서 반드시 지정해야 하는 사항은 아닙니다.', 'AXA'),
('고객지원·기타', '보험수익자가 무엇입니까?', '보험수익자란 기명피보험자의 자손/자상담보의 사망보험금을 수령할 수 있는 분을 의미하며 보험가입시 지정하실 수있습니다', 'AXA'),
('고객지원·기타', '차량에 장착된 부속품이 부속품 목록에 없습니다', '부속품 목록에서 기타를 선택하시고 해당 부속품의 가액을 입력하시면 됩니다.', 'AXA'),
('고객지원·기타', '전방조종자동차란 무엇입니까?', '전방조정자동차라 함은 ‘자동차안전관리 기준에 관한 규칙’에 의거하여 차량의 앞부분과 조향장치까지의 길이가 차량전체 길이의 1/4이내인 승합자동차를 말합니다. 예를 들어 그레이스 베스타 프레지오 이스타나 등은 전방조종 승합자동차이며 비전방조종 자동차는 카니발 카렌스 싼타모 갤로퍼 스타렉스 카스타 등이 있습니다.', 'AXA'),
('고객지원·기타', '교통법규위반을 적용하는 기준은 무엇입니까?', '교통법규 위반 경력요율이란 고객님의 법규위반 사항을 보험료에 반영하는 것으로 과거2년간의 교통법규위반 경력이 한번도 없으시다면 보험료를 할인 받으시고 법규위반 경력이 있으면 보험료에서 할증을 받게 됩니다. 개인용군 업무용군 영업용 이륜자동차보험 중 개인 소유차량에 대해서만 적용하며 회사차를 운전하다 법규위반을 하였다면 회사차에 할증되는것이 아니고 개인이 소유하고 있는 차에 할증됩니다. 즉 본인이 위반한 법규할증은 본인의 보험료에 할증됩니다. 전전년 5월1일부터 당년 4월30일까지의 위반경력이 당년 9월1일부터 익년 8월31일 사이에 가입하는 계약에 대하여 적용합니다. 단 법규위반 실적기간이 2년 미만인 경우에는 당해 실적기간을 평가기간으로 합니다.', 'AXA'),
('상품·보장 안내', '자기신체사고와 자동차상해는 어떤 차이가 있나요?', '자기신체에 대한 손해는 ''자기신체사고'' 와 ''자동차상해''중에서 고객님의 선택에 따라 선택하여 가입하실 수 있습니다. 자기신체사고는 부상사고의 경우 상해급수별 한도내 실제치료비만 보상되나 자동차상해는 가입금액 내 상해급수별 한도없이 실제치료비외에 위자료 휴업손해 기타 손해배상금등을 보상받을수 있습니다.', '하나손해보험'),
('가입·보험료', '운전면허증이 없는 경우 가입이 불가능한가요?', '운전자보험은 피보험자가 도로교통법 제43조 제44조에 의한 음주 무면허 상태에서 운전하던 중 사고는 보상하지 않습니다. 따라서 무면허 상태로는 가입은 가능하나 운전자비용손해(벌금 방어비용 교통사고처리지원금 면허정지 면허취소 자동차사고위로금등)는 보상 되지 않습니다.', '하나손해보험'),
('가입·보험료', '비운전자도 가입할 수 있나요?', '네 가입할수 있습니다. 다만 운전자에게 해당하는 특약을 제외한 나머지 특약에 대해서만 가능합니다.(운전자 해당 특약 : 교통사고처리지원금 벌금 자동차사고변호사선임비용 운전중 뺑소니 무보험차 교통상해 자동차사고성형치료비)', '하나손해보험'),
('가입·보험료', '무통장입금으로 결제하였을 경우 현금영수증 발급이 가능한가요?', '자동차보험료는 신용카드 또는 현금으로 결제하셔도 ''보장성보험료로 별도 소득공제대상이 되므로 현금영수증발급은 불가능하며 연말에 자동차보험료 납입증명서가 계약자에게 일괄발송되거나 국세청 연말정산간소화서비스를 통해 확인하실 수 있습니다.', '하나손해보험'),
('가입·보험료', '자동차보험료를 분할로 결제 할 수 있나요?', '자동차보험료를 나누어 내는 방법에는 크게 2가지가 있습니다.보험사에 지로또는 자동이체를 통해 분할납입하는 방법과 일시납보험료를 신용카드를 통해 할부결제하는 방법입니다.보험사에 분할납입하는 방법은 [ 비연속 2회납 연속 2회납~6회납]중에 선택가능하며 단 보험료를 분할하여 납입하는 경우 분할 납부하는 방식과 횟수에 따라 1년보험료의 0.5~1.5%의 분납할증율이 추가됩니다. 또한 분납보험료가 제 때에 납입되지 않는 경우 납입최고기간을 두어 보험계약의 해지를 일정기간 유예하며 유예기간이 경과하면 보험계약이 해지됩니다.또한 의무보험인 대인배상l과 대물배상에 대하여는 분납이 불가능하여 초회보험료가 전체보험료의 70%이상을 차지하게됩니다. 따라서 보험사의 분할납부보다는 일시납으로 가입 후 신용카드의 무이자 할부를 이용하여 결제 하는 것이 더 유리합니다.', '하나손해보험'),
('가입·보험료', '새차를 구입해서 보험들면 얼마정도 되나요?', '자동차보험료는 운전자의 연령이나 성별 범위 뿐 아니라 구입하시는 차량별 가입담보별 각 담보별 가입금액에 따라서 보험료가 모두 달라집니다. 홈페이지(www.hanainsure.co.kr)의 ‘신규가입’ 메뉴에서 고객님의 보험료를 쉽고 편리하게 알아보실 수 있습니다.', '하나손해보험'),
('가입·보험료', '책임보험(의무보험)이 무엇인가요?', '자동차보험은 책임보험(의무보험)과 임의보험으로 구분할 수 있습니다. 책임보험은 자동차소유자면 누구나 자동차사고시 최소한의 피해자 보호를 위해 제정 된 자동차손해배상보장법에 의해 의무적으로 가입해야 하는 일종의 강제보험입니다. 2005년 2월 이전에는 자동차사고로 인한 다른 사람이 사망하거나 부상을 입은 경우에 일정액의 보상금이 나오는 ''책임보험(대인배상Ⅰ)''만 있었으나 2005년 2월부터 다른 사람의 재물피해를 입힌 경우에도 일정액의 보상금이 나오는 책임보험(대물배상)가입도 의무화되었습니다. 만약 미(지연)가입 시에는 과태료가 부과됩니다.(자동차 손해배상보장법 제40조 제3항 제1호)', '하나손해보험'),
('가입·보험료', '군에서 운전한 경우 자동차보험 가입경력 인정되나요?', '군에서 운전병으로 복무하셨다면 운전기간 만큼을 가입경력으로 인정받아 할인을 적용 받을 수 있습니다. 군복무 중 운전경력을 인정받고자 하시는 고객께서는 으로 연락주시거나 환급서비스 신청을 해주시기 바랍니다. ① 인정기준 : 군에서 운전병으로 복무한 경우② 제출서류 : 병적증명서(병무청) - 입대일 전역일 운전병과 및 운전경력기간 표시 (단 교육훈련기간은 제외)', '하나손해보험'),
('가입·보험료', '기명피보험자가 무엇인가요?', '기명피보험자란 자동차보험 증권상에 기재된 분을 말합니다. 기명피보험자는 계약자와 구분이 필요합니다. 기명피보험자는 자동차를 소유하고 있는 사람. 즉 자동차등록증상 소유자를 뜻하며 등록증상의 소유자를 피보험자로 해야 사고 발생 시 보상을 받습니다. 계약자는 보험료를 납입하는 주체로서 연말정산 소득공제 혜택을 받습니다. 계약자와 피보험자는 서로 다르게 설정하실 수 있습니다.', '하나손해보험'),
('가입·보험료', '미성년자도 자동차보험 가입할 수 있나요?', '자동차보험 가입에 대해서는 별도의 연령제한을 두고 있지 않습니다.그러나 자동차운전면허증의 취득이 18세부터 가능하고 자동차보험은 자동차보유자만이 가입이 가능하기 때문에 미성년자라 하더라두 자동차등록증상의 소유자인지 여부는 확인해야 하고 운전면허가 없는경우에는 실제 운전자에 맞게 운전자범위 및 운전연령 등 특약 선택하실 때 주의하셔야 합니다.', '하나손해보험'),
('가입·보험료', '보험료를 할부로 결제하였는데 중간에 신용카드유효기간이 종료되었을땐 어떻게 하죠?', '자동차보험료 결제시 무이자할부카드를 이용하여 결제한 경우 보험기간 중간에 카드 유효기간이 만료되어도 수수료면제 혜택은 할부종료시까지 계속 유효합니다.', '하나손해보험'),
('특약·할인', '차량 5부제는 어떤 차량이 가입 대상인가요?', '보험회사가 정한 ‘차량 5부제 참여 신청서’를 제출한 경우 피보험자동차의 차량가액이 5 000만원 미만인 경우친환경차(전기·수소차)가 아닌 경우', '하나손해보험'),
('특약·할인', '차량 5부제 특별약관이란 무엇인가요?', '차량번호 끝자리에 따라 지정된 요일에 차량을 운행하지 않을 경우 자동차보험료를 할인해주는 특별약관입니다.운행 제한일 : 월요일 1․6 화요일 2․7 수요일 3․8 목요일 4․9 금요일 5․0 (주말․공휴일 제외)', '하나손해보험'),
('특약·할인', '자랑스런 선생님 패키지특약이란 무엇일까요?', '자랑스런 선생님 패키지 특약은 대인배상Ⅰ 대물배상에 가입한 경우에 가입하실 수 있는 특약서비스 입니다. 학교생활 중 교직원에게 발생 가능한 6가지 자동차 사고위험을 보장하는 상품으로 운전범위 내 운전자가 교직원으로 재직 중인 경우 가입이 가능합니다. 보장항목으로 ● 유가족 위로금 ● 방학 또는 연수중 사고위로금 ● 원격지사고 숙박 및 귀가보상지원금 ● 교내 주차상태사고 보상지원금 ● 전근시사고위로금 ● 부부교직원상해위로금이 있습니다.', '하나손해보험'),
('특약·할인', '연령한정특약이란 무엇일까요?', '운전할 수 있는 운전자의 연령을 특정 나이로 제한함으로써 보험료 계산시 차등을 두는 특약입니다. 주민등록상의 생년월일의 만 나이를 기준으로 해당 연령한정특약 미만의 자가 피보험자동차를 운전하던 중에 발생한 사고에 대해서는 보상처리가 불가능합니다.', '하나손해보험'),
('특약·할인', '블랙박스 장착후 보험료 할인을 받으려면 어떻게 하나요?', '웹/모바일에서 자동차보험을 가입하거나 부속품 추가로 계약변경을 원하시는 경우에는 부속품 정보에 블랙박스 장착여부를 선택하신후 구입년월과 금액을 입력하고 차량정면사진과 차량내부 블랙박스 장착사진을 등록해주시면 됩니다. 단 보험료 할인적용 후 사고발생시 블랙박스를 미장착하였거나 정상적으로 작동하지 않은 경우 보험료가 추징될 수 있는 점 유의하시기 바랍니다.', '하나손해보험'),
('특약·할인', '[마일리지 특약] 마일리지 자동차보험이 어떤 건가요?', '이 상품은 차량의 주행거리에 따라 보험료를 할인해주는 ‘마일리지 특별약관'' 상품으로 보험가입 시 주행거리를 약정여부에 따라 후할인 받는 특별약관 상품입니다. 운행 빈도가 낮아 주행거리가 길지 않은 고객님께서는 특약 가입을 통해 보험료를 절감하실 수 있습니다.', '하나손해보험'),
('특약·할인', '[마일리지 특약] 얼마나 할인 받을 수 있나요?', '* 마일리지 주행거리 할인율은 보험상품＞자동차·운전자＞마일리지할인특약 안내(https://www.hanainsure.co.kr/w/product/carDriver/educarCMmileage/mileageSale)에서 자세히 확인하실 수 있습니다.', '하나손해보험'),
('특약·할인', '[마일리지 특약] 가입대상은 어떻게 되나요?', '1년 정상계약일 경우 마일리지 특약을 가입할 수 있으며 중도가입도 가능합니다. 개인소유 승용자동차 개인소유 화물(1 2 3 4종 경화물) 및 승합(1 2 3 종 경승합) 차량에 대해서 가입이 가능합니다.', '하나손해보험'),
('계약관리·변경', '보험가입 후 결제한 신용카드를 변경 할 수 있나요?', '자동차보험은 보험효력이 발생한 이후에는 결제하는 신용카드 변경이 불가능합니다.', '하나손해보험'),
('계약관리·변경', '타인명의의 차량을 자동차보험에 가입할 수 있나요?', '아닙니다.자동차보험은 등록증상 소유주와 기명피보험자가 동일하게만 가입이 가능합니다.자동차보험은 등록증상 소유주 앞으로 보험을 가입하고 운전범위 및 운전연령특약 선택시 원하시는 조건으로 가입하시면 됩니다.', '하나손해보험'),
('사고접수·보상', '내가 자동차사고로 피해 입을 경우를 대비하려면 어떤보험을 가입하면 좋을까요?', '‘자기신체사고(또는 자동차상해 특별약관)’ ‘자기차량손해’에 가입하시면 내가 낸 자동차사고에서 나와 동승자(직계가족인 부모 배우자 및 자녀인 경우의 동승자)의 신체피해 내 차량의 피해를 보상받을 수 있습니다.', '하나손해보험'),
('사고접수·보상', '자동차보험 가입시 법률비용을 보상받을 수 있는 특약이 있나요?', '자동차보험 가입시 또는 보험기간 중 다음과 같은 특약 상품을 선택하여 가입할 수 있습니다.● 형사합의지원금 특별약관 : 피보험자동차를 소유 사용 관리하는 동안에 생긴 피보험자동차의 사고로 인하여 타인을 사망케 하거나 다치게 하여 형사합의를 한 경우 약관에 따라 보험금을 지급합니다. ● 방어비용지원 특별약관 : 피보험자동차를 소유 사용 관리하는 동안에 생긴 피보험자동차의 사고로 인하여 피보험자가 구속 또는 공소제기 기소(단 약식기소 제외)된 경우 약관에 따라 보험금을 지급합니다.● 벌금비용담보 특별약관 : 피보험자동차를 소유 사용 관리하는 동안에 생긴 피보험자동차의 사고로 인하여 확정 판결에 의하여 피보험자가 부담하여야 하는 경우 약관에 따라 보험금을 지급합니다.', '하나손해보험'),
('사고접수·보상', '[자동차보상] 자기부담금이란 무엇인가요?', '자기차량 사고수리시 손해액 (수리비 등)의 일정비율(예: 20%)을 피보험자가 부담하는 것으로 수리비 등의 누수를 방지하여 전체 보험가입자의 보험료 인상 등 경제적 부담을 경감하기 위한 제도입니다.Tip) 자기부담금은 피보험자가 정비업체에 직접 납부하셔야 하며 보험사는 자기부담금을 제외한 금액을 정비업체에 지급합니다. 단 피보험자가 실제 확정된 자기 부담금을 초과하여 부담한 경우 차액분에 해당하는 금액을 환급해드립니다. 자기부담금제는 자기차량손해에만 적용되며 대물배상에는 적용되지 않습니다', '하나손해보험'),
('사고접수·보상', '[자동차보상] 대물배상의 지급기준의 대차료 인정기간은 어떻게 되나요?', '피해차량이 수리가능한 경우에는 수리를 위해 자동차정비업자에게 인도하여 수리가 완료될때까지의 기간이며 한도는 25일(실제 정비작업기간이 160시간을 초과하는 경우에는 30일)까지입니다. 단 부당한 수리지연이나 출고지연 등의 사유로 인해 통상의 수리기간(보험개발원이 과거 3년간 렌트기간과 작업시간 등과의 상관관계를 합리적으로 분석하여 산출한 수리기간)을 초과하는 기간은 인정되지 않습니다. 만약 피해차량이 수리가 불가능한 경우에는 10일을 한도로 합니다', '하나손해보험'),
('사고접수·보상', '[자동차보상] 피해차량이 대차를 하지 않는 경우 대차료 지급기준은 어떻게 되나요?', '동급의 대여자동차가 있는 경우에는 동급의 최저요금 대여자동차 대여 시 소요되는 통상의 요금의 35% 상당액을 지급합니다 「여객자동차운수사업법」에 따른 운행연한 초과로 동급의 대여자동차를 구할 수 없는 경우에는 피해차량과 동일한 규모의 대여자동차 중 최저요금의 대여자동차를 빌리는데 소요되는 통상의 요금의 35% 상당액을 지급합니다.', '하나손해보험'),
('사고접수·보상', '자동차보험에 가입하면 언제부터 보상되나요?', '도 일반 자동차보험과 같이 보장하는 내용은 똑같습니다. 자동차보험의 보상을 받을 수 있는 개시시점은 전 계약이 만기되어 다시 가입한 가입당일 24시부터이며 만약 차량을 처음 구입하여 보험에 처음 가입하는 경우에는 보험료를 납부한 시점부터 보상 받으실 수 있습니다.', '하나손해보험'),
('사고접수·보상', '차량에 장착된 카오디오만을 도난당했습니다. 이것도 보상이 가능한가요?', '자기차량손해는 보험에 가입한 자동차 전부의 도난으로 인한 손해를 보상하며 차량에 장착된 일부 부분품 등의 도난에 대해서는 보상하지 않습니다. ※ 자기차량손해 보장에서 보험계약시 보험회사에 알려주지 않은 자동차의 부속품 및 피보험자동차의 일부 부분품 부속품 부속기계장치만의 도난으로 인한 손해는 자기차량손해 사고시 보상하지 않습니다.', '하나손해보험'),
('사고접수·보상', '가지급보험금이란 무엇인가요?', '보험사고가 발생한 후 보험금 지급 사유의 조사 및 확인에 상당한 시일이 소요되거나 피해자가 장기간 치료를 받게 됨으로 인하여 자동차보험 등 보험약관에서 정한 기일내에 보험금을 지급하지 못할 것으로 예상되는 경우 피해자가 경제적 어려움에서 조속히 벗어날 수 있도록 하기 위하여 일정한 범위내에서 미리 지급하는 보험금을 말합니다.', '하나손해보험'),
('사고접수·보상', '대물배상의 대차료 지급기준은 어떻게 되나요?', '대차를 하는 경우 대여자동차는 「여객자동차운수사업법」에 따라 등록한 대여사업자에게서 차량만을 빌릴 때를 기준으로 동급의 대여자동차 중 최저요금의 대여자동차를 빌리는데 소요되는 통상의 요금을 지급합니다. 그러나 피해차량이 사고시점을 기준으로 「여객자동차운수사업법」에 따른 운행연한 초과로 동급의 대여자동차를 구할 수 없는 경우에는 피해차량과 동일한 규모의 대여자동차 중 최저 통상요금의 대여자동차를 기준으로 합니다. 만약 대여자동차가 없는 경우에는 사업용 해당 차종 휴차료일람표 범위에서 실임차료를 지급합니다. 단 5톤이하 또는 밴형 화물자동차 및 대형 이륜자동차(260cc초과)의 경우 중형승용차급 중 최저 통상요금 한도로 대차 가능합니다.', '하나손해보험'),
('사고접수·보상', '병원에 입원치료중인 피해자입니다. 현재 입원중인 병실에 여러 명이 함께 있어 여러 가지로 불편해요.', '자동차보험환자의 경우 해당병원의 대중적인 일반병실을 기준으로 입원료를 지급하도록 되어 있습니다. 피해자가 불편하여 상급병실을 사용하고자 한다면 대중적인 일반병실과의 병실료 차액을 본인이 부담하여야 합니다.', '하나손해보험'),
('사고접수·보상', '무보험차에 부상당한 피해자입니다. 가입한 자동차보험에서 처리 받을 수 있나요?', '무보험자동차상해 담보에 가입한 경우 보상이 가능합니다. 무보험자동차상해 담보는 대인배상Ⅰ·Ⅱ 대물배상 자기신체사고(또는 자동차상해 특별약관)에 가입하는 경우 가입 가능하며영업용의 경우 ‘무보험자동차에 의한 상해담보 특별약관’으로 가입하셔야 합니다. ※ 1인당 보험증권에 기재된 보험가입금액 한도내 지급', '하나손해보험'),
('사고접수·보상', '가지급보험금 제도는 무엇인가요?', '가지급보험금은 자동차사고 등 피해자가 경제적 어려움에서 조속히 벗어날 수 있도록 하기 위해서 운영되고 있는 제도입니다.보험사고가 발생한 후 보험금 지급 사유의 조사 및 확인에 상당한 시일이 소요되거나 피해자가 장기간 치료를 받게 됨으로 인하여 보험약관에서 정한 기일내에 보험금을 지급받지 못해 경제적으로 어려움을 겪고 있는 분들이 가지급보험금 제도를 이용하면 도움을 받을 수 있습니다.', '하나손해보험'),
('긴급출동·차량서비스', '긴급출동서비스특약은 어떤 차종이 가입할 수 있습니까?', '가입가능한 차종은 승용자동차 / 경 1 2 3종승합자동차 / 경 1 2 3 4종화물자동차 이며 이륜차량 및 건설기계차량 등 일부차종은 제외됩니다. 차종의 구분에 따라 가입가능한 특약 상품이 달라질 수 있습니다.', '하나손해보험'),
('긴급출동·차량서비스', '긴급출동서비스는 총 몇 회까지 이용가능 한가요?', '긴급출동서비스특약은 자동차보험기간 1년동안 총 6회까지만 무료 이용이 가능하며 6회까지 모두 이용한 시점부터는 자동 종료됩니다. 이용횟수 조정 및 추가 가입은 불가능하며 특약이 종료된 이후에는 서비스요청에 따라 발생하는 비용을 직접 부담하셔야합니다.(보험가입 기간에 따라 서비스이용 횟수에 제한이 있을 수 있습니다. ) (예) 6개월 미만인 경우는 총 3회 3개월미만 1회 제공) 단 비상급유 서비스의 경우 1일당 1회에 한하여 연간 총 2회를 한도로 하며 3개월 미만의 경우 1회의 서비스를 제공합니다.', '하나손해보험'),
('운전자보험', '[운전자보험] 교통사고가 아닌 속도위반이나 신호위반으로 벌금을 청구해도 보상이 가능한가요?', '단순 교통법규위반으로 인한 범칙금은 보험금 지급 대상이 아닙니다. 자동차를 운전하던 중에 발생한 급격하고도 우연한 자동차사고로 타인의 신체에 상해를 입히거나(자동차사고벌금/대인) 도로교통법 제151조(벌칙)에 따른 벌금형이 확정된 경우(자동차사고벌금/대물) 벌금액을 1사고당 보험가입금액을 한도로 보상합니다.', '하나손해보험'),
('운전자보험', '[운전자보험] 음주운전 사고도 운전자보험으로 보상받을 수 있나요?', '음주운전 사고는 12대 중과실사고에 포함되어 교통사고처리지원금 벌금 변호사선임비용과 같은 비용관련 특약은 보상하지 않습니다. 다만 본인 신체와 관련된 사망 후유장해 입원일당 자동차사고부상치료비 등은 보상합니다.', '하나손해보험'),
('운전자보험', '[운전자보험] 자차 단독사고 후 보험사에 접수를 안했어요. 자동차부상치료비 보상이 가능한가요?', '자동차사고부상치료비는 교통사고로 상해를 입고 자배법에서 정한 자동차사고부상등급표의 상해등급을 받은 경우 등급에 따라 보상을 받는 특약입니다. 그러나 당 사고로는 보험사에 사고접수를 하지 않아 교통사고 발생을 고객님이 입증하는 경우에만 보상이 가능합니다. 이에 준비하셔야 할 보상서류는 병원기록지(경우에 따라 진단서 추가 제출 필요) 등 이 필요합니다.', '하나손해보험'),
('상품·보장 안내', '대인배상Ⅰ과 대인배상Ⅱ의 차이점이 뭔가요?', '대인배상Ⅰ Ⅱ 담보에 대해서 안내드립니다. 대인배상Ⅰ:자동차사고로 타인을 다치거나 사망하게 한 경우 [자동차손해배상보장법]에서정한 한도내에서 보상하는담보 (차량의 소유주라면 법적으로 가입이 강제화 되어 있는 담보입니다.) 대인배상Ⅱ:자동차사고로 타인을 다치거나 사망하게 한 경우 대인1을 초과한 손해액보상', 'KB손해보험'),
('상품·보장 안내', '법인업무용 자동차보험은 개인용과 어떻게 다른가요?', '가장 중요한 구분은 자동차의 소유자가 누구인가 하는 것입니다. 법인사업자 명의로 소유하고 있는 모든 차량은 법인업무용 자동차보험으로 가입하야합니다. 반면 개인용 자동차보험은 승차정원 10인승 이하 개인 소유 자가용승용차를 출퇴근과 가족나들이 등 일상적인 용도로 사용할 때 가입하는 보험입니다. 보다 자세한 문의는 ☎1544－0077연락바랍니다.', 'KB손해보험'),
('상품·보장 안내', '법인자동차의 임직원한정 범위는 어디까지인가요?', '법인 업무용 임직원 운전자는 아래와 같습니다. 1. 기명피보험자 소속의 이사와 감사 2. 기명피보험자 소속의 직원(계약직 직원을 포함하며 계약직 직원의 경우 피보험자와 체결한 근로계약에 한정합니다) 3. 기명피보험자의 업무를 위해 피보험자동차를 운행하는 자로 기명피보험자와 계약관계에 있는 업체에 소속된 자 4. 기명피보험자의 업무를 위하여 필요하다고 인정되는 경우로 기획재정부령으로 정하는 사람', 'KB손해보험'),
('상품·보장 안내', '무보험차상해담보는 무엇인가요?', '보험에 가입하지 않은 차량이나 뺑소니에 의해 피보험자 본인 및 그 가족(부모 배우자 및 자녀) 운전범위에 포함되는 피보험자가 죽거나 다쳤을때 보상을 해드리는 담보 입니다.', 'KB손해보험'),
('상품·보장 안내', '대물배상이 무엇인가요?', '대물배상이란 자동차사고로 타인의 차량이나 재물을 없애거나 훼손한경우 보상해주는 담보입니다. * 1사고당 2천만원은 의무가입입니다.', 'KB손해보험'),
('상품·보장 안내', 'ABS 이모빌라이저가 무엇인가요?', '■ABS란? Antilock Break System의 약자로서 주행 중 급제동을 할 때 타이어가 잠기는 것을 방지하여 급제동시에도 지면과 타이어의 마찰을 계속 유지시켜 핸들 조작이 가능하도록 한 장치입니다. ■이모빌라이저(IM)란? 자동차키(손잡이)안에 트랜스폰더라는 칩이 내장되어있어 차량에 맞는 칩이 들어있는 자동차키로 복제를 한 후 입력장비로 자동차에 연결하여 입력해야 시동이 가능한 도난방지시스템을 말합니다. 따라서 ABS나 이모빌라이저가 장착된 차량은 사고 위험율을 줄여주기 때문에 특별요율을 적용하여 일정율의 보험료 할인 혜택이 적용됩니다.(단 ABS장착특별요율은 책임개시 2015.11.16일자 할인폐지) 보다 자세한 문의는 ☎1544－0077연락바랍니다.', 'KB손해보험'),
('상품·보장 안내', '삼성헬스를 사용하는데 삼성헬스를 통해서는 걷기 인정이 안되나요?', '네. 현재(21.07.01)는 안됩니다. 그러나 현재 제휴 중에 있고 최대한 빠른시간 안에 삼성헬스앱을 통한 걷기 기록도 인정되도록 시스템 작업중에 있습니다.', 'KB손해보험'),
('상품·보장 안내', '전기자동차 보험이란 무엇인가요?', '전기차를 운전하는 고객에게 자동차 보험료를 할인 및 전기차 맞춤 서비스를 지원해 드리는 자동차보험 상품입니다. * 2021년 6월 18일 책임개시 계약부터 적용됩니다. * 할인율 평균 12.2% (가솔린차량 대비)', 'KB손해보험'),
('가입·보험료', '운전직으로 근무한 경우 보험가입경력으로 인정을 해주나요?', '네~ 가능합니다. 보험가입경력이외에 운전직으로 근무한 경우에도 보험가입경력을 인정받을 수 있습니다. ■가입경력이 인정되는 경우 법인체에서 운전직으로 근무한 기간 군대에서 운전병으로 근무한 기간 관공서에서 운전직으로 근무한 기간 택시나 버스의 운전기사로 근무한 기간 ※ 택배 운전경력 지게차 운전경력 운전면허시험장 운전경력 법인체가 아닌 곳의 운전경력 취급업자 운전자보험(대리운전)등은 가입경력을 인정하지 않습니다. ■운전경력이 확인 가능한 별도의 서류 제출 필수 보다 자세한 문의는 ☎1544－0077연락바랍니다.', 'KB손해보험'),
('가입·보험료', '회사소유 자동차를 직원이 출퇴근용으로 사용하고 있는 경우에는 보험가입을 어떻게 하나요?', '자동차보험은 자동차를 소유한 사람이 누구냐 자동차의 종류가 무엇인가에 따라서 보험종목이 결정됩니다. 승용차의 경우에는 소유자가 개인이면 개인용자동차보험에 가입해야하고 소유자가 법인인 경우에는 업무용자동차보험에 가입해야 합니다. 질문과 같이 비록 직원이 출퇴근용으로만 사용해도 소유자가 회사일 경우에는 (법인)업무용자동차보험에 가입해야 합니다. 회사소유의 자동차보험은 법인용 자동차보험 메뉴를 통해 가입하실 수 있습니다.', 'KB손해보험'),
('가입·보험료', '의무보험만 가입해도 되나요?', '의무보험만 가입할 경우 과태료 등의 불이익은 없습니다. 다만 사고로 인해 의무보험을 초과하는 손해가 발생할 경우 교통사고처리특례법상의 형사처벌 등의 특례를 인정받지 못해 형사처벌을 받을 수 있습니다.', 'KB손해보험'),
('가입·보험료', '법인자동차보험을 개인이 가입할 수 있나요?', '법인자동차보험 계산/가입 시 피보험자를 법인 보험계약자는 법인의 대표로 하여 가입하실 수 있습니다. 보험료 결제 시에는 법인대표 개인명의의 신용카드만 이용이 가능합니다.', 'KB손해보험'),
('가입·보험료', '의무보험이란 무엇인가요?', '의무보험은 자동차손해배상보장법 제 5조에 의해 자동차보유자가 반드시 가입해야하는 보험을 말합니다. 자동차보험의 대인배상Ⅰ과 대물배상(2천만원)이 의무보험에 해당합니다.', 'KB손해보험'),
('가입·보험료', '오토바이도 보험가입 의무대상이 있나요?', '네. 오토바이도 보험가입 의무대상이 있습니다. ■가입대상 1인 또는 2인을 운송하며 배기량이 50cc 이상 이륜차 ■ 이륜차포함대상 ① 조향장치의 조작방식 동력전달방식 또는 원동기 냉각방식 등이 이륜의 자동차와 유사한 구조로 되어있는 삼륜 또는 사륜의 자동차로서 승용자동차에 해당하지 아니하는 자동차 ② 이륜인 자동차에 측차를 붙인 자동차 (사이드카) ■의무보험 가입의무 적용기준 ''08년 12월31일 이전부터 운행되고 있는 차량 :''09년.6.30일까지 가입 ''09년 1월 1일 이후 새로 구입하는 차량 : 구입시점부터 가입 보다 자세한 문의는 ☎1544－0077연락바랍니다.', 'KB손해보험'),
('가입·보험료', '개인대리운전상품은 누가 가입할 수 있나요?', '대리운전업을 영위하는 대리기사들 누구나가 가입할 수 있습니다. 기존 대리운전보험(단체)은 중복가입을 해야 하는 경우가 많고 보험료가 비쌉니다. 이런 이유로 개인대리운전보험을 가입합니다.', 'KB손해보험'),
('특약·할인', '마일리지환급금을 갱신계약 대체보험료로 사용 요청하였으나 현금으로 돌려받고 싶습니다. 가능한가요?', '네. 가능합니다. 갱신계약 체결 시 마일리지 환급금을 대체사용하지 않으시거나 타사로 갱신계약을 체결하신 경우 또는 단순 변심 등으로 현금으로 환급을 받고자 하시는 경우에는 콜센터를 통해 환급요청하시면 계좌로 송금하여드립니다.', 'KB손해보험'),
('특약·할인', '걸음수할인특약이란?', '17일 이상 하루 5천보 이상 걸으신 분에게 자동차 보험료 할인이 적용되는 특약입니다. ▶ 걸음수 할인특약 가입안내 1. 적용대상 : 개인용 자동차보험 (승용 다인승 가입가능) 2. 가입가능대상 : 가입일 이전 30일동안 17일 이상 하루 5천보 이상 달성된 경우 할인적용담보 : 대인배상 대물배상 자기신체사고 무보험차상해 자기차량손해담보 (긴급출동서비스 특약보험료는 할인대상 보험료에서 제외)', 'KB손해보험'),
('특약·할인', '걸음수 기준에 미달되어 가입당시 걸음수할인특약을 가입하지 못했습니다. 도중에 추가가입이 가능한가요?', '네 가능합니다. 할인대상기준(조건)에 충족된다면 배서기준일로부터 보험 종료일까지 남은 보험기간에 대해 변경배서를 통해 보험료를 할인해드립니다. 걸음수 할인특약 할인적용 담보 : 대인배상 대물배상(확장) 자기신체사고(자상) 무보험차상해 자기차량손해(포괄) * 긴급출동서비스 특약보험료는 할인대상 보험료에서 제외됩니다.', 'KB손해보험'),
('특약·할인', '이륜차도 블랙박스를 장착하면 할인해주나요?', '네. 이륜차도 블랙박스 장착시 보험료가 할인됩니다. * 가입시 블랙박스가 부착된 이륜차 사진을 첨부해야합니다.', 'KB손해보험'),
('특약·할인', '걸음수할인특약 가입시 부부한정 특약으로 가입한 경우 기명피보험자와 배우자 중 걸음수가 더 많은쪽으로 조회하여 가입이 가능한가요?', '아니오. 불가합니다. 부부한정특약으로 가입하신 경우도 걸음수는 기명피보험자의 걸음수만 인정됩니다.', 'KB손해보험'),
('특약·할인', '형 동생 언니와 함께 운전하는 경우 가족한정으로 가입할 수 있나요?', '가족한정은 형제자매가 포함되지 않습니다. 운전자 범위를 가족 및 형제자매로 선택해 가입해주세요.', 'KB손해보험'),
('특약·할인', '대중교통이용할인특약 가입자입니다. 걸음수할인특약과 중복가입이 가능한가요?', '대중교통이용할인특약이 가입된 차량의 경우에는 걸음수 할인특약을 중복으로 가입하실 수 있습니다.', 'KB손해보험'),
('특약·할인', '실버교통안전교육 이수 할인이 무엇인가요?', '실버교통안전교육 이수 할인 특약 어떤 경우 보상하나요? 실버교통안전교육을 이수하고 보험회사에서 그 사실을 확인할 수 있는 서류를 제출하고 보험회사의 승인을 얻어 보험료를 할인받는 특약입니다. 특약을 가입하려면? 다음 조건을 모두 만족하는 경우에 한해서 가입할 수 있습니다. 1. 기명피보험자가 만 65세 이상인 경우 2. 기명피보험자가 도로교통공단에서 실시하는 고령운전자 교통안전교육을 이수하고 인지지각검사결과 총 점수가 42점 이상인 경우 또는 인지능력 자가진단 결과지의 운전능력검사결과표 종합 판정이 1등급 내지 3등급인 경우 (단 온라인으로 실시되는 고령운전자 교통안전교육은 결과지의 인지능력 자가진단 결과가 ''수료''등급인 경우에도 가입 가능합니다.) 3. 위 인지지각 검사일로부터 보험증권에 기재된 보험기간의 첫날까지 경과기간이 2년을 넘지 않는 경우 또는 인지능력자가 진단일로부터 보험증권에 기재된 보험기간의 첫날까지 경과기간이 3년을 넘지 않는 경우 4. 기명피보험자한정 운전특약 또는 부부한정 운전특약을 가입한 경우', 'KB손해보험'),
('특약·할인', '전자우편(보험증권외) 특약가입은 어떻게 하나요?', '가입시 보험증권을 제외한 보험계약안내자료를 전자우편(모바일 또는 E-mail)으로 수령을 체크하여 가입하는 경우 보험료를 할인받을 수 있습니다. 보험계약 안내자료란? 보험약관 및 분납/만기안내 만기예고안내 등의 서류를 말합니다.', 'KB손해보험'),
('특약·할인', '전자우편(보험증권외)특약은 어떤특약인가요?', '보험증권을 제외한 보험계약 안내자료를 전자우편(모바일 및 E-mail) 으로 수령해 자원을 절약할 수 있는 친환경 특약입니다. 또한 비용절감을 통해 보험료 할인혜택을 받을 수 있습니다. (단 증권은 우편물로 수령)', 'KB손해보험'),
('계약관리·변경', '카드할부와 분납은 어떻게 다른가요?', '카드할부는 보험료 전체 금액을 선택하신 할부 개월수에 따라 나누어 보험료가 청구되는 것이며 분납은 의무보험인 대인Ⅰ과 대물배상은 일시납으로 납입하고 나머지 담보를 선택하신 분납 횟수에 따라 나누어 납입하는 것입니다. * 분납의 경우 대인Ⅰ과 대물배상 담보가 일시납이기 때문에 카드할부보다 첫달에 납입하시는 보험료가 많습니다.', 'KB손해보험'),
('계약관리·변경', '자동차 갱신(재가입)보험료를 미리 알고 싶은데 계산이 안됩니다. 왜그런걸까요?', '자동차보험료를 계산하기 위해서는 보험료를 구성하는 요율정보(가입경력 할인할증 등)가 필요합니다. 요율정보는 만기일로부터 대략 30일~45일 이전에 확정되므로 갱신(재가입)보험료는 만기일로부터 대략 30일~45일 이내부터 확인이 가능합니다.', 'KB손해보험'),
('계약관리·변경', '계약자와 입금자가 달라도 되나요?', '입금자가 달라도 됩니다. 단 연말정산 시 계약자가 소득공제를 받으신다면 입금자는 받으실 수 없으니 유의해주세요.', 'KB손해보험'),
('계약관리·변경', '질권설정이 무엇인가요?', '리스 자동차를 이용하는 경우 자동차의 권리가 리스사에 있음을 보험계약에 반영하기 위한것입니다. 자기차량손해 담보를 가입한 경우에만 차량가액 내에서 질권설정이 가능합니다. <질권설정을 위해서 구비해야할 사항> 1. 리스사의 사업자번호 2. 리스사명 3. 질권설정 금액', 'KB손해보험'),
('계약관리·변경', '자동차보험 만기일자를 놓쳤습니다.', '만기일자가 지나면 사고시 보상을 받을 수도 없고 의무보험 미가입으로 과태료가 부과될 수도 있으니 만기일을 지켜 미리미리 갱신하시는 것이 좋습니다.', 'KB손해보험'),
('계약관리·변경', '자동차 신규등록은 언제까지 해야하나요?', '자동차의 임시운행 허가 기간은 10일이며 10일 이내에 관할 자동차등록사업소에서 자동차 신규등록해야합니다. 임시운행허가기간 경과 후 신규등록할 경우에는 과태료가 부과됩니다. 과태료는 운행허가기간 경과 후 10일 이내 3만원 10일을 초과한 경우에는 매1일 초과시 마다 1만원 추가 최고 100만원까지 부과됩니다. 보다 자세한 문의는 ☎1544－0077 로 연락바랍니다.', 'KB손해보험'),
('계약관리·변경', '차량대체는 무엇인가요?', '차량대체는 기존 차량을 매매 또는 폐차 후 차량을 새로 구입하였을때 기존 보험을 해지하지 않고 새 차량으로 대체하는 것입니다.', 'KB손해보험'),
('계약관리·변경', '새로 출고한 자동차보다 중고차의 자동차보험료가 더 비싼가요?', '보험료는 차량가액 이외에도 자동차의 연식 등급 등 다양한 내용이 반영되어 산출됩니다. 신차보다 중고차의 차량가액이 낮더라도 등급과 연식 등에 따라 보험료가 높게 책정될 수 있습니다.', 'KB손해보험'),
('사고접수·보상', '자동차사고가 발생하였습니다. 사고접수를 어떻게 하나요?', '자동차보험에 가입된 경우 고객콜센터(15440114)로 전화 주셔서 ARS 1번을 선택하시면 사고접수 및 상담을 받으실수 있습니다.', 'KB손해보험'),
('사고접수·보상', '후청구서비스가 무엇인가요?', '후청구 서비스는 결제일과 보험개시일이 10일이상 차이가 나는 경우 카드 청구를 결제일이 아닌 보험개시일에 청구하는 서비스입니다. 카드대금 청구지연은 최대 30일까지 가능하며 여러 대의 자동차 보험료를 한번에 결제하는 경우에는 서비스 이용이 불가합니다.', 'KB손해보험'),
('사고접수·보상', '법인용 자동차보험을 가입하면 보상이 다른가요?', '다이렉트에서 가입하시는 모든 자동차보험은 보상서비스를 동일하게 받을 수 있습니다. 법인용 자동차보험도 든든한 보상망과 서비스 이용 가능하오니 안심하세요~ 보다 자세한 문의는 ☎1544－0077연락바랍니다.', 'KB손해보험'),
('상품·보장 안내', '운전면허증이 없어도 기명피보험자가 될 수 있나요?', '운전면허증이 없어도 자동차등록증상 명의자라면 기명피보험자가 될 수 있습니다.', '삼성화재'),
('상품·보장 안내', '2종 보통면허로 12인승 승합차를 운전하면 무면허에 해당하나요?', '운전할 수 있는 자동차 종류를 위반했으므로 무면허에 해당합니다.', '삼성화재'),
('상품·보장 안내', '고령운전자 교통안전교육을 이수했는데 유효기간이 있나요?', '고령운전자 교통안전교육 이수 시 유효기간은 2년입니다.발급일부터 보험기간 첫날까지 2년이 지나지 않은 교육이수증만 인정합니다. 단 2019년 1월 1일 이후 체결한 계약은 발급일부터 보험기간 첫날까지 3년이 지나지 않은 교육이수증만 인정합니다.', '삼성화재'),
('가입·보험료', '무번호(차대번호) 상태인 차량도 자동차보험에 가입할 수 있나요?', '네 가입할 수 있습니다. 자동차보험 가입 후 자동차번호가 확정되면 홈페이지에서 자동차번호를 등록하거나 담당RC에게 요청해 주세요.', '삼성화재'),
('가입·보험료', '대인/대물 담보는 꼭 가입해야 하나요?', '네 대인/대물 담보는 책임보험이므로 반드시 가입해야 합니다.대인배상은 사망과 후유장애 시 최고 1억 5 000만원 부상 시 최고 3 000만원 한도로 보상하고 대물배상은 2 000만원까지 의무가입해야 합니다. 가입하지 않으면 과태료 처분 및 벌금 등 형사적 불이익을 받을 수 있습니다.', '삼성화재'),
('특약·할인', 'Eco 마일리지 환급금 정산 특약이 무엇인가요?', '이전 계약에서 마일리지 특약을 가입하고 돌려받을 환급금이 있는 경우 따로 환급받지 않고 갱신 보험료에서 바로 차감하는 특약입니다.', '삼성화재'),
('특약·할인', '마일리지 특약은 정산 후 언제 환급되나요?', '약관에서는 운행정보를 제공받은 날로부터 10일 안에 보험료를 정산하도록 명시하고 있습니다.피보험자와 계약자 등에게 귀책사유가 없는데도 10일을 초과하여 보험료를 정산하지 않은 경우에는 초과기간 동안의 이자(보험개발원이 공시한 보험계약대출이율)를 더해서 지급합니다.', '삼성화재'),
('특약·할인', '마일리지 특약은 정산 어떻게 진행하면 되나요?', '자동차보험 만기 1개월 전이나 만기 후 1개월 이내에 주행거리 확인용 사진을 제출하면 됩니다.주행거리 확인용 사진은 계기판 사진과 자동차번호판 사진 각 1장씩 필요합니다.자동차보험을 해지한 경우에도 1개월 이내에 사진을 제출하면 가입기간 동안의 보험료에서 정산해 드립니다.', '삼성화재'),
('특약·할인', '사실혼 관계도 운전자한정 특약을 부부한정으로 가입하면 보험 처리되나요?', '사실혼 관계도 부부한정으로 가입할 수 있으며 보험 처리도 가능합니다.', '삼성화재'),
('특약·할인', '보험기간 중에 가입경력인정자를 등록해도 가입경력이 인정되나요?', '가입경력인정자 등록 시 실제 운전을 시작한 날짜를 기준으로 경력을 인정받을 수 있습니다. 책임개시일부터 운전했다면 책임개시일을 가입기간 중간부터 운전했다면 운전을 시작한 날짜를 변경기준일로 선택하면 됩니다.', '삼성화재'),
('특약·할인', '가입경력인정자를 등록하면 보험료가 얼마나 할인되나요?', '보험료는 할인되지 않습니다.가입경력인정자 등록은 운전경력을 인정받기 위한 제도이며 현재 계약의 보험료에 영향을 주지 않습니다.다만 등록한 사람이 추후 자동차보험을 가입할 때 경력을 인정받아 보험료를 절약할 수 있습니다. [가입경력인정자 제도란?]기명피보험자가 지정한 사람(최대 2인)의 보험 가입경력을 인정하는 제도입니다. 실제 운전경험은 있는데 보험 가입경력이 인정되지 않아 최초가입자로 분류되어 보험료 부담이 생기는 것을 줄이기 위해 만들어졌습니다.', '삼성화재'),
('특약·할인', '임시운전자 특약을 하루만 가입할 수도 있나요?', '하루만도 가입 가능합니다.[임시운전자 특약 가입 안내]- 가입기간: 최소 1일부터 최대 30일까지- 모니모 앱 또는 홈페이지에서 가입가능 바로가기> 임시운전자 특약 가입', '삼성화재'),
('특약·할인', '이륜차보험도 나눔친서민 특약을 가입할 수 있나요?', '네 가입할 수 있습니다.2012년 5월 30일부터 이륜차보험의 나눔친서민 특약 가입이 가능해졌으며 차량 요건을 제외한 가입 조건은 개인용/업무용 자동차보험과 동일합니다.', '삼성화재'),
('특약·할인', '이륜차보험 나눔친서민 특약 가입 조건이 궁금해요.', '차량 요건을 제외한 가입 조건은 개인용/업무용 자동차보험과 동일합니다.이륜자동차보험 나눔친서민 특약의 차량 요건은 4년 이상 경과된 배기량 100cc 이하의 가정용/비유상배달용 이륜자동차이며 2대 이하면 가입할 수 있습니다.(단 기명피보험자가 국민기초생활 보장법 제2조에 의거한 기초생활 수급자인 경우 차량 요건이 적용되지 않습니다.)', '삼성화재'),
('특약·할인', '업무용 법인 소유 차량도 임시운전자 특약에 가입할 수 있나요?', '업무용 법인 소유 차량은 승용차종만 임시운전자 특약에 가입할 수 있습니다.', '삼성화재'),
('특약·할인', '렌트비용지원 특약과 교통비지원 특약을 둘 다 가입할 수 있나요?', '렌트비용지원 특약과 교통비지원 특약은 중복 가입할 수 없습니다.', '삼성화재'),
('특약·할인', '만 60세의 경우에도 고령운전자 교통안전교육 이수자 할인을 받을 수 있나요?', '고령운전자 교통안전교육 이수자할인은 만 65세 이상부터 가능합니다.만 60세인 경우에는 고령운전자 교통안전교육 이수자할인을 받을 수 없습니다.', '삼성화재'),
('특약·할인', '가입경력인정자 제도가 무엇인가요?', '기명피보험자가 지정한 사람(최대 2인)의 보험 가입경력을 인정하는 제도입니다. 실제 운전경험은 있는데 보험 가입경력이 인정되지 않아 최초가입자로 분류되어 보험료 부담이 생기는 것을 줄이기 위해 만들어졌습니다.', '삼성화재'),
('특약·할인', '가입경력인정자 등록 조건이 있나요?', '연령한정 특약 운전자한정 특약 조건에 맞는 운전자 중 가족(부모 자녀 배우자)만 등록할 수 있습니다.운전자 범위가 ''가족 및 형제자매''인 경우 기명피보험자의 형제자매도 등록할 수 있고 ''지정 1인 추가''인 경우 지정 1인도 등록할 수 있습니다.단 기명피보험자 1인 한정 특약은 가입경력인정자를 등록할 수 없습니다.', '삼성화재'),
('특약·할인', '가족운전자한정 특약으로 배우자와 자녀가 운전을 하는데 두 사람 모두를 가입경력인정자로 등록할 수 있나요?', '가족운전자한정 특약으로 최대 2명까지 가입경력인정자를 등록할 수 있습니다.', '삼성화재'),
('특약·할인', '만 65세 이상 고령운전자가 교통안전교육 이수자 할인을 받으려면 어떻게 하나요?', '''기명피보험자 1인 한정'' 또는 ''부부운전자한정운전'' 특약에 가입하고 도로교통공단에서 ''고령운전자 교통안전교육''을 이수한 뒤 운전능력검사 결과로 등급이 명시된 교육이수증을 제출하면 됩니다.', '삼성화재'),
('특약·할인', '자동차보험에서 연령한정 특약의 기준은 ''만 나이''인가요?', '자동차보험 연령한정 특약의 기준은 ''만 나이''이며 주민등록상 생년월일을 기준으로 합니다.', '삼성화재'),
('특약·할인', '부모님의 이혼으로 어머니와 거주중인데 친아버지 차를 내가 운전해도 가족한정 특약이 적용되나요?', '가족운전자한정 특약이 적용됩니다.부모의 이혼으로 편부 또는 편모와 거주하더라도 연령한정 등의 특약이나 면허에 문제가 없다면 가족운전자한정 특약의 범위에 포함됩니다.', '삼성화재'),
('특약·할인', '기명피보험자 1인 한정운전 특약에 가입했는데 다른 사람이 운전해도 되나요?', '다른 사람은 운전할 수 없으며 기명피보험자만 운전 가능합니다.', '삼성화재'),
('특약·할인', '가족 및 형제자매 한정운전 특약에 처제나 형수도 포함되나요?', '형제자매 한정운전 특약에 처제나 형수는 포함되지 않습니다.', '삼성화재'),
('특약·할인', '피보험자가 시어른이고 운전자 범위가 가족한정이면 손자도 운전할 수 있나요?', '가족한정 운전자 범위에 손자는 포함되지 않습니다.', '삼성화재'),
('특약·할인', '이륜차부담보 특약은 직접 운전하지 않고 뒷좌석에 타기만 해도 보상을 못 받나요?', '뒷좌석 탑승도 이륜차부담보 특약의 면책사유이므로 보상받을 수 없습니다.단 이륜차 소유자 및 사고 상황에 따라 실제 보상 가능 여부가 달라질 수 있으니 보상담당자에게 문의해 주세요.', '삼성화재'),
('특약·할인', '승용차도 유상운송 특약에 가입할 수 있나요?', '승용차도 유상운송 위험담보 특약에 가입할 수 있으며 가입 시 유상운송에 따라 보상이 가능합니다.단 6인승 이하의 피보험자동차를 사용하여 「여객자동차운수사업법」상 여객자동차운송사업에 해당하는 운송(유상으로 여객 운송)을 하는 중 발생한 사고는 보상받을 수 없습니다.', '삼성화재'),
('특약·할인', '자기차량손해 보장에 가입하지 않아도 다른 자동차 차량손해 지원 특약에 가입할 수 있나요?', '자기차량손해 보장에 가입하지 않았다면 다른 자동차 차량손해 지원 특약을 가입할 수 없습니다.다른 자동차 차량손해 지원 특약은 자기차량손해 또는 차량단독사고 손해보상 특별약관에 가입한 경우에만 함께 가입할 수 있습니다.', '삼성화재'),
('특약·할인', '무보험자동차에 의한 차량손해 특약 가입 조건이 궁금해요.', '무보험 자동차에 의한 상해에 가입하고 자기차량손해에 가입하지 않은 경우에만 가입할 수 있습니다.', '삼성화재'),
('특약·할인', '무보험자동차에 의한 차량손해 특약의 보상한도 기준이 궁금해요.', '보험가액을 한도로 보상받을 수 있습니다.', '삼성화재'),
('특약·할인', '무보험자동차에 의한 차량손해 특약은 자기차량손해 기준으로 보상되나요?', '무보험 자동차에 의한 차량손해 특약은 대물배상 기준으로 보상됩니다.해당 특약으로 사고 차량의 수리비와 간접손해비용(렌트비 교통비 등)을 보상받을 수 있습니다.', '삼성화재'),
('특약·할인', '주차해둔 차가 파손됐어요. 무보험자동차에 의한 자기차량손해 또는 차량단독사고 손해보상 특약으로 보상되나요?', '무보험자동차에 의한 차량손해 지원 특별약관은 ''무보험자동차에 의한 상해''에 가입하고 ''자기차량손해''에 가입하지 않은 경우에만 가입할 수 있으며 가해 차량과 배상의무자가 확인되는 경우에만 보상받을 수 있습니다.따라서 주차 중 차량이 파손되었더라도 손해를 끼친 차량을 알 수 없다면 보상받을 수 없습니다.챠량단독사고 손해보상 특약은 자기차량손해에 가입한 경우 함께 가입할 수 있으며 손해를 끼친 차량 확인 여부와 관계없이 보상받을 수 있습니다.', '삼성화재'),
('특약·할인', '친구가 운행 중 상대방 차를 파손시켰어요. 가족한정 특약으로 대물배상 1 000만원까지는 보험 처리되는 게 맞나요?', '가족 범위 외의 다른 사람이 차량을 운행했으므로 파손 차량을 보상하지 않습니다. 가족한정 특약 조건에 위배되는 경우 대물배상은 하지 않습니다.다만 다친 사람이 있다면 대인배상Ⅰ 가입금액 한도로 보상합니다.', '삼성화재'),
('계약관리·변경', '입고확인서로 자동차보험을 해지할 수 있나요?', '입고확인서만으로는 의무보험인 자동차보험을 해지할 수 없습니다. [자동차보험 해지 필요서류]-말소사실증명서 폐차인수증명서 자동차등록원부(갑) 중 1가지 의무보험을 해지할 수 있는 사유는 「자동차손해배상 보장법」 제25조에 규정되어 있고 해당 유형이 아닌 경우 보험사가 임의해지할 수 없습니다. 폐차장에 차량을 입고한 경우 「자동차손해배상 보장법」에 규정된 의무보험 해지 가능한 사유가 아닙니다. 국토교통부는 「자동차관리법」 제58조 제5항 제1호에 따라 자동차해체재활용업자가 해당 자동차 자동차등록증 등록번호판 및 봉인을 인수하고 그 사실을 증명하는 서류를 발급한 경우 의무보험 해지를 허용하고 있습니다.', '삼성화재'),
('계약관리·변경', '보험기간 중에 새 차를 구입했는데 차량대체 신청은 어떻게 하나요?', '모니모와 홈페이지에서 차량대체를 신청할 수 있으며 다이렉트 가입 고객인 다이렉트 홈페이지에서도 신청할 수 있습니다.바로가기> 자동차보험 계약 변경(차량대체)', '삼성화재'),
('계약관리·변경', '운휴기간 환급은 모든 차량에 적용되나요?', '운휴기간 환급은 영업용 차량에만 적용됩니다.', '삼성화재'),
('계약관리·변경', '운휴기간 환급 신청은 어디서 하나요?', '운휴기간 종료 후 담당RC를 통해 신청할 수 있습니다. 고객콜센터에서는 신청할 수 없습니다.', '삼성화재'),
('계약관리·변경', '차량이 압류되었는데 자동차보험을 해지할 수 있나요?', '차량 압류 이후 다른 사람에게 차량을 이전한 경우에만 자동차보험을 해지할 수 있습니다.', '삼성화재'),
('계약관리·변경', '자동차보험 가입 시 차량가액은 어떻게 정해지나요 ?', '자동차보험 가입 시 차량가액은 보험개발원에서 정한 차량기준가액표에 따릅니다.단 보험개발원 차량기준가액표에 없거나 보험사가 정한 일부 차종은 보험사 기준에 따릅니다.', '삼성화재'),
('계약관리·변경', '외국인등록번호가 없는 외국인도 보험 가입이나 자동차를 운전할 수 있나요?', '외국인등록번호가 없어도 보험 가입 및 자동차를 운전할 수 있습니다. 단 자동차 운전은 국제면허증이 있어야만 가능합니다.', '삼성화재'),
('계약관리·변경', '자동차보험 영문증명서(무사고/영문가입)는 어디서 신청하나요?', '모니모 앱과 홈페이지에서 발급받을 수 있습니다.증명서는 다운로드가 가능하며 이메일 또는 팩스를 선택한 경우 2일(영업일 기준) 안에 받을 수 있습니다.바로가기 > 영문증명서 발급', '삼성화재'),
('계약관리·변경', '자동차보험 분납 보험료 자동이체정보를 홈페이지에서 변경할 수 있나요?', '아니요 변경할 수 없습니다.자동차보험 분납 보험료 자동이체계좌 및 이체일은 담당RC를 통해 변경해 주세요.', '삼성화재'),
('사고접수·보상', '미국시민권자이고 미국 운전면허증만 있는데 사고가 났을 때 국제면허증이 없어도 보상받을 수 있나요?', '국제면허증이 없으면 무면허 운전에 해당하므로 보상하지 않습니다.국제면허증이 있어야 국내에서 운전할 수 있으며 운전면허 상호인정 국가/지역인 경우 우리나라 면허증으로 교환받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '임신 중 교통사고 입원치료를 받았는데 상해로 보상받을 수 있나요?', '교통사고로 인한 치료에 대해서만 보상 가능하며 임신과 관련된 의료비는 보상에서 제외됩니다.', '삼성화재'),
('사고접수·보상', '자동차보험으로 사고를 처리했는데 장기보험과 연계해서도 보상받을 수 있나요?', '자동차보험으로 사고 처리 후 가입한 장기보험에 관련된 담보가 있는 경우 보상 연계접수 및 심사가 진행됩니다.심사 과정에서 필요한 경우 추가서류를 요청드릴 수 있습니다.', '삼성화재'),
('사고접수·보상', '음주운전으로 면허가 정지됐는데 보상받을 수 있나요?', '음주운전으로 인한 면허정지는 보상받을 수 없습니다.에서 판매하는 비용손해 약관에는 공통적으로 ''보상하지 아니하는 손해'' 항목에 ''피보험자의 음주·무면허 상태 또는 약물 상태에서 운전''이 포함되어 있습니다.따라서 무면허운전이나 음주운전을 한 경우 면허취소 및 면허정지 위로금뿐만 아니라 비용손해도 보상받을 수 없습니다. ※ 비용손해란? 벌금 면허정지위로금 면허취소위로금 방어비용 등을 의미하며 무면허나 음주 외에 도주로 인한 비용손해도 보상되지 않습니다.', '삼성화재'),
('사고접수·보상', '교통사고로 자동차보험에서 보상을 받았는데 개인보험으로도 입원치료비를 보상받을 수 있나요?', '자동차보험으로 처리한 의료비는 중복 보상되지 않습니다.단 상해의료비 담보에 가입한 경우에는 가입 시기에 따라 일부 보상받을 수 있습니다.- 2003년 10월 이전 계약: 자동차보험에서 처리받은 의료비의 100% 보상- 2003년 10월 이후 계약: 자동차보험에서 처리받은 의료비의 50% 보상', '삼성화재'),
('사고접수·보상', '자동차보상을 받았는데 보험금지급내역서를 찾을 수 없어요.', '보험금지급내역서는 보상 처리가 완결된 건에만 지급금액이 표시됩니다.에 자동차보험에 가입되어 있다면 아래와 같이 발급받을 수 있습니다.- 피보험자/운전자: 피보험자/운전자용 보험금지급내역서- 대인피해자: 치료비지급내역서- 대물피해자: 수리비지급내역서- 자기신체손해/무보험 보상 받은 피보험자: 치료비지급내역서 발급 가능- 자기차량손해 보상을 받은 피보험자: 수리비지급내역서', '삼성화재'),
('사고접수·보상', '3년사고요율이 무엇인가요?', '3년사고요율은 가입경력이 1년 이상인 피보험자의 보험료를 직전 3년 및 1년 동안의 사고 건수에 따라 차등하는 적용하는 요율입니다.사고 건수와 점수에 따라 3년사고요율 및 할인할증등급이 결정되고 이에 따라 보험료가 변경될 수 있습니다.', '삼성화재'),
('사고접수·보상', '정부보장사업은 보험금 청구 시효가 있나요?', '정부보장사업은 사고발생일부터 3년 안에 보험금을 청구해야 합니다.정부보장사업 보상처리를 위해 경철서에 반드시 신고해야하며 위탁기관인 자동차손해배상진흥원에 손해입증자료(교통사고 사실 확인원 진단서 치료비 영수증 등)를 제출하여 청구할 수 있습니다.', '삼성화재'),
('사고접수·보상', '폐차 후 신규등록비용지원금은 받았는데 초과수리비용은 보상을 받지 못했어요.', '초과수리비용지원 특약은 피보험차량을 실제 수리하는 경우에만 보상받을 수 있습니다.폐차한 경우에는 차량을 수리한 것이 아니기 때문에 보상되지 않습니다.', '삼성화재'),
('사고접수·보상', '교통사고사실확인원은 어디서 발급받나요?', '가까운 경찰서나 지구대 민원실 경찰민원포털 경찰청교통민원24 정부24에서 발급받을 수 있습니다.해당 사고 관련자 본인(사고운전자 피해자) 본인에게 적법한 위임을 받은 사람만 교통사고사실확인원을 발급받을 수 있습니다. 위임받은 사람은 위임장을 반드시 지참해야 하고 인터넷 발급은 본인인증이 필요합니다.', '삼성화재'),
('사고접수·보상', '법률지원방어비용 특약에 가입하면 대인사고 발생 시 변호사 비용을 보상받을 수 있나요?', '네 보상받을 수 있습니다.피보험자가 구속되거나 검사에 의해 공소가 제기되어 변호사를 선임하게 된 경우 변호사 선임비가 지출되었을 때만 보상한도 안에서 실손보상됩니다.단 약식기소된 경우에는 보상되지 않습니다.', '삼성화재'),
('사고접수·보상', '아들이 운전한 무보험 차량에 사고를 당했는데 무보험자동차상해로 보상받을 수 있나요?', '아니요 보상받을 수 없습니다.무보험자동차상해는 약관상 기명피보험자의 부모 배우자 자녀 및 운전자의 부모 배우자 자녀에 해당하는 자가 배상의무자인 경우 보상하지 않는다고 명시되어 있습니다.', '삼성화재'),
('사고접수·보상', '다른 차량이 내 차를 파손한 뒤 도주했는데 정부보장사업으로 보상받을 수 있나요?', '정부보장사업은 대인 피해를 보상하는 제도로 차량 파손과 같은 물적사고는 보상받을 수 없습니다.단 자기차량손해 또는 차량단독사고 손해보상 특약에 가입한 경우에는 해당 특약으로 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '렌터카를 운전하다가 사고가 났어요. 제 차의 다른 자동차 차량손해 특약으로 보상받을 수 있나요?', '다른 자동차 차량손해 지원 특별약관Ⅱ에 가입했다면 보상받을 수 있습니다.단 해당 특약은 아래 조건을 모두 충족하는 경우에만 보상됩니다.① 사업용자동차 중 승차정원이 10인승 이하의 대여자동차(렌터카)② 대여기간 7일 이내③ 렌터카 운전 중 발생한 사고로 인한 차량 손상', '삼성화재'),
('사고접수·보상', '주차해둔 차가 긁혔는데 다른 차대차 충돌 및 도난사고 한정 약관으로 보상되나요?', '자기차량손해는 다른 자동차와의 충돌이나 접촉 피보험자동차 도난으로 인한 손해만 보상됩니다.따라서 차량단독사고 손해보상 특약이 가입되어 있지 않다면 특정되지 않은 가해자에 의한 차량 긁힘 손해는 보상받을 수 없습니다.', '삼성화재'),
('사고접수·보상', '미국여행에서 운전하다 생긴 사고도 국내 자동차보험으로 보상되나요?', '해외에서 운전 중 발생한 사고는 국내 자동차보험으로 보상받을 수 없습니다.국내 자동차보험으로는 대한민국(북한 포함) 안에서 생긴 사고만 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '렌트비도 과실상계 적용되나요?', '네 렌트비도 과실상계 적용됩니다. *''과실상계''란?채무 불이행이나 불법 행위에 대해 채권자나 피해자에게도 과실이 있는 경우 법원이 이를 고려해 배상액을 정하는 제도', '삼성화재'),
('사고접수·보상', '벌금을 내지 않아 면허 기소중지 상태인데 무면허에 해당하나요?', '경찰서에서 확인해야 합니다. 기소중지 사유가 면허와 인과관계가 있는지 알아야 하기 때문에 현재 상황만으로는 정확히 판단할 수 없습니다. 경찰서 확인이 어렵다면 운전면허관리공단에서 면허 유효 여부를 확인할 수 있습니다. 면허가 유효하다면 기소중지 상태에서 사고가 발생해도 무면허는 아닙니다.', '삼성화재'),
('사고접수·보상', '법률지원 특약에 가입하면 음주운전 사고 시 형사합의금도 보상되나요?', '음주로 인한 사고는 법률지원 특약의 보상 범위에 해당하지 않습니다.', '삼성화재'),
('사고접수·보상', '운전 중 보행자를 보고 멈췄는데 접촉은 없었지만 보행자가 넘어졌어요. 저에게 과실이 있나요?', '자동차 운행이 사고의 원인이 되었다고 판단되면 배상책임이 발생할 수 있습니다.단 사고 경위에 따라 과실 여부가 달라질 수 있으므로 가까운 경찰서에 신고하여 정확한 사실관계를 확인해 주세요.보험 처리 가능 여부는 보험사 보상담당자에게 문의해 주세요.', '삼성화재'),
('사고접수·보상', '피보험자는 아버지인 저로 얼마 전 결혼한 딸이 운전하다 사고가 났습니다. 가족한정 특약으로 보상되나요?', '자녀가 결혼했더라도 가족한정 특약상 ''자녀''에 포함되므로 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '만 26세 이상 연령한정 특약에 미리 가입했어요. 아직 생일이 지나지 않았는데 사고가 나면 보상받을 수 있나요?', '아직 만 26세가 되지 않았다면 해당 특약으로 대인배상Ⅱ와 물적사고는 보상받을 수 없습니다.단 다친 사람이 있다면 대인배상Ⅰ로 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '부모님이 제 차로 사고를 내셨어요. 다치지는 않았지만 차는 많이 파손됐는데 가족한정 특약으로 보상받을 수 있나요?', '가족한정 특약 자기차량 담보에 가입했다면 보상받을 수 있습니다.단 자기부담금이 발생하므로 그 비용은 부담하셔야 합니다.', '삼성화재'),
('사고접수·보상', '대물배상 2 000만원 한도 가입 의무화는 언제부터 적용됐나요?', '2016년 4월부터 대물배상 사고 1건당 2 000만원으로 가입이 의무화되었습니다.', '삼성화재'),
('사고접수·보상', '뺑소니 사고란 정확히 어떤 것을 말하나요?', '뺑소니 사고란 사고를 내고 그냥 가는 것 즉 도주하는 것을 말합니다. [뺑소니에 해당할 수 있는 경우]- 사고 때문에 피해자가 사망하거나 다쳤을 것이라는 사실을 안 경우(''다쳤을 것 같다''고 인지한 정도만으로도 뺑소니 인정됨)- 다친 피해자를 구호하는 등의 조치를 하지 않고 도주할 의사로 현장을 이탈한 경우- 현장을 이탈함으로써 누가 사고를 냈는지 쉽게 알지 못하게 한 경우- 구호 조치는 했으나 치료비를 지급할 가해자의 이름과 연락처를 교환하지 않은 경우 [뺑소니에 해당하지 않는 경우]- 다른사람에게 의뢰해 피해자를 후송하고 연락처를 주고 받아 사후 처리를 한 경우결론적으로 사고 후 피해자의 상태를 확인하지 않고 현장을 이탈하거나 피해자가 경미한 부상을 입었다고 판단하여 구호 조치 없이 떠나는 경우 등이 해당 됩니다.', '삼성화재'),
('사고접수·보상', '교통사고처리특례법이 무엇인가요?', '교통사고처리특례법''이란 업무상 과실 또는 중대한 과실로 교통사고를 일으킨 운전자가 종합보험 가입증명서를 제시하면 형사처벌을 면제하는 법률입니다. 종합보험은 대인배상 무한 대물배상 2 000만원 이상에 가입해야 하고 가입증명서는 보험가입사실증명서를 말합니다. 단 사망 및 도주 12대 중과실(중상해사고 포함)인 경우는 형사처벌 면제 조건에서 제외합니다.', '삼성화재'),
('사고접수·보상', '무보험차상해 담보의 보상한도가 궁금해요.', '무보험차상해 담보는 1인당 보험증권에 기재된 보험가입금액(2억 5억 7억 10억) 한도에서 과실상계 후 실제 손해액을 기준으로 보상됩니다.[공제금액 안내]- 대인배상Ⅰ(책임공제 및 정부보장사업을 포함)에 의하여 지급될 수 있는 손해금액- 배상의무자가 가입한 대인배상Ⅱ 또는 공제계약에 의하여 지급될 수 있는 금액- 피보험자가 탑승 중이었던 자동차가 가입한 대인배상Ⅱ 또는 공제계약에 의하여 지급 될 수 있는 금액- 피보험자가 배상의무자로부터 이미 지급받은 손해배상액(형사합의금 등)- 배상의무자가 아닌 제3자가 부담할 금액으로 피보험자가미 지급받은 금액', '삼성화재'),
('사고접수·보상', '자동차사고로 다치면 어떤 부분을 보상받을 수 있나요?', '부상보험금을 보상받을 수 있습니다.항목별 세부 규정은 자동차보험 약관을 참조하거나 보상담당자에게 문의해 주세요. [부상보험금 항목]- 적극손해(구조수색비 치료관계비)- 위자료- 휴업손해- 간병비(책임보험 상해구분상 1~5급에 해당하는 경우)- 그 밖의 손해배상금', '삼성화재'),
('사고접수·보상', '「자동차손해배상 보장법」은 어떤 법인가요?', '자동차사고 피해자를 보호하기 위해 제정한 법률입니다. 자동차를 소유한 사람이면 누구나 보험에 가입해야 한다는 의무 등을 규정하고 있습니다.', '삼성화재'),
('사고접수·보상', '자기신체손해 담보에 가입하면 교통사고 치료비를 전액 보상받을 수 있나요?', '상해급수별 보험가입금액 한도에서 실제 지출한 치료비만 보상받을 수 있습니다. [보상기준 안내]- 단독사고- 자기과실 100% 사고', '삼성화재'),
('사고접수·보상', '장애인용 전동휠체어도 면허가 필요한가요?', '장애인의 이동을 돕는 전동휠체어는 면허가 없어도 됩니다. 「도로교통법」 제80조 제1항에 따라 원동기를 단 자동차 중 「교통약자의 이동편의 증진법」 제2조 제1호에 따른 교통약자가 최고속도 시속 20km 이하로만 운행될 수 있는 차를 운전할 경우는 면허가 필요하지 않습니다.', '삼성화재'),
('사고접수·보상', '사고로 차량이 파손됐는데 바로 수리하기가 어려워요. 견적만으로 수리비용을 청구할 수 있나요?', '자기차량손해 담보의 일방과실사고의 경우에는 실제 수리를 원칙으로 합니다. 다만 「민법」의 금전배상원칙에 따라 피해차량에 대한 대물배상 쌍방과실이 확정되어 교차처리하는 자기차량손해는 수리비 견적만으로도 보험금 청구가 가능할 수도 있으니 정확한 내용은 보상담당자와 상의해 주세요.', '삼성화재'),
('사고접수·보상', '친구가 운행 중 사고를 냈어요. 가족한정 특약으로 보상되나요?', '가족 범위 외의 다른 사람이 차량을 운행했으므로 보상하지 않습니다. 가족 범위 외의 다른 사람이 차량을 운행한 경우 보상을 받으려면 임시운전자 특약에 가입해야 합니다.모니모 앱 또는 홈페이지 담당RC를 통해 가입할 수 있습니다. 바로가기> 임시운전자 특약 가입', '삼성화재'),
('사고접수·보상', '교통사고로 아이가 다쳐 간병인이 필요한데 간병비도 보험 처리되나요?', '2017년 3월 1일 이후 책임개시 계약부터 간병비도 보험 적용됩니다. 간병비 관련 표준약관(2017년 3월 개정)- 피해자 본인이 상해 1~2급이면 60일 3~4급이면 30일 5급이면 15일 한도로 실제 입원일수만큼 간병비 지급- 동일한 사고로 부모 중 1인이 사망했거나 1~5급 상해를 입은 7세 미만 자녀가 입원한 경우 최대 60일 한도로 실제 입원기간 동안의 간병비 지급- 간병비는 실제 간병인 사용 여부와 관계없이 지급하며 위의 두 케이스가 중복되는 경우는 둘 중 액수가 큰 금액을 지급', '삼성화재'),
('사고접수·보상', '운전 중 차 밖으로 던진 물건에 사람이 다쳤는데 보상되나요?', '아니요 보상되지 않습니다.운전 중 차 밖으로 던진 물건에 다른 사람이 다친 경우는 보상 대상이 아닙니다.', '삼성화재'),
('사고접수·보상', '지진으로 차량이 파손됐는데 보상받을 수 있나요?', '지진은 천재지변에 해당하므로 파손된 차량은 보상되지 않습니다.', '삼성화재'),
('사고접수·보상', '휴업손해 보상 기준이 어떻게 되나요?', '세법 등에 따른 객관적 소득 손실 자료를 보험사에 제출하면 소득감소액의 85%를 인정받을 수 있습니다. [휴업손해 보상기준 안내]- 부상으로 인하여 휴업함으로써 수입의 감소가 있었음을 관계 서류를 통해 증명할 수 있는 경우에 한하여 휴업기간 중 피해자의 실제 수입 감소액의 85% 해당액을 지급함- 소득이 없는 무직자이거나 수입이 감소되지 않은 경우 휴업손해액이 지급되지 않음- 현재 휴업손해 기준은 2017년 3월 개정된 표준약관을 근거로 2017년 3월 1일 이후 책임개시 계약 건부터 지급비율 상향(80% → 85%)', '삼성화재'),
('사고접수·보상', '주차된 차를 밀다가 파손시켰는데 제가 가입한 자동차보험으로 보상되나요?', '차량을 소유·사용·관리 중 발생한 사고가 아니므로 가해자의 자동차보험으로 대물배상할 수 없습니다.주차된 다른 차를 밀다가 파손시킨 경우에는 차를 밀던 사람이 직접 배상해야 합니다.단 파손된 차량이 자기차량손해에 가입되어 있다면 해당 담보로 먼저 보상받을 수 있습니다. 이 경우 피해차량의 보험사는 지급한 보험금에 대해 가해자에게 변제할 것을 청구(구상권 행사)합니다.', '삼성화재'),
('사고접수·보상', '신호 대기 중인 차를 뒤에서 추돌했는데 피해차량 운전자가 음주 상태였다면 과실비율이 달라지나요?', '상대방 운전자의 음주 사실이 사고 발생과 무관하다고 판단되면 과실상계 대상이 되지 않습니다.단 피해차량 운전자의 음주운전은 「도로교통법」에 따라 별도 처벌받게 됩니다.', '삼성화재'),
('사고접수·보상', '공소제기가 무엇인가요?', '범죄 혐의가 있다고 판단되는 피의자에 대해 국가형벌권을 발동해 법원에 재판의 소를 제기하는 것을 ''공소제기''라고 합니다.''검찰의 기소''라고도 합니다.', '삼성화재'),
('사고접수·보상', '정차란 어떤 상태를 말하나요?', '차가 5분을 초과하지 않고 정지하는 것으로 주차 외의 정지 상태를 말합니다.', '삼성화재'),
('사고접수·보상', '''과실상계''란 무엇인가요?', '사고 발생 원인과 내용으로 보아 상대방 또는 제3자에게도 과실이 있는 경우 그 비율을 정하고 손해배상액을 산정할 때 그 비율에 해당하는 금액을 공제하거나 부담시키는 것을 ''과실상계''라고 합니다. 참고로 민법과 대법원 판결문에서는 ''과실상계''를 아래와 같이 정의하고 있습니다. 「민법」 제396조 제763조불법행위(不法行爲)나 채무불이행(債務不履行)으로 인한 손해배상청구(損害賠償請求)의 경우에 그 손해의 발생 또는 그 증대에 대하여 피해자(채권자 배상권리자)에게도 과실이 있으면 배상유무 및 손해액을 정하는 데 참작하는 것이다. 대법원 1999· 2· 26 선고 98다52469불법행위에 있어서 피해자의 과실은 가해자의 과실과 달리 사회통념이나 신의성실의 원칙에 따라 공동생활에 있어 요구되는 약한 의미의 부주의를 의미합니다.', '삼성화재'),
('사고접수·보상', '정부보장사업과 무보험차상해는 한도 차이가 있나요?', '정부보장사업은 「자동차손해배상 보장법」에서 정한 ''대인배상Ⅰ'' 한도에서 보상하고 ''대인배상Ⅰ''에서 보장하는 금액을 초과하는 손해는 무보험차상해 담보 가입금액한도에서 보상합니다.', '삼성화재'),
('사고접수·보상', '자동차사고로 번호판을 바꿔야 하는데 대물보상으로 처리되나요?', '가해차량이 있다면 그 차량의 대물 담보로 보상받을 수 있습니다.주소지 상관없이 가까운 구청의 자동차등록계 또는 소재지 차량등록사업소에서 번호판을 재발급하고 영수증을 보험사에 제출하면 번호판 교체비용을 보상받을 수 있습니다.또한 차량 일부가 파손되어 수리가 필요한 경우에는 수리비도 함께 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '고장으로 인한 차량 손해도 보상되나요?', '차량 고장으로 인한 손해는 보상되지 않습니다.', '삼성화재'),
('사고접수·보상', '중상해 여부는 누가 판단하나요?', '중상해 여부는 의사의 진단 소견을 토대로 검찰이 판단합니다. 의사는 진단을 할 뿐 중상해 여부를 판단하지 않습니다. 다만 경찰이나 검찰 등 수사기관에서 요청하는 경우 중상해 요건에 해당하는지에 대한 의학적 소견을 피력할 수는 있습니다.', '삼성화재'),
('사고접수·보상', '운행 중 차량이 침수됐는데 보상되나요?', '차량단독사고 손해보상 특약 또는 자기차량 침수·화재 피해 한정 보상 특약에 가입했다면 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '차량 옵션으로 추가 장착한 고가의 고급 오디오가 사고로 파손됐어요. 보상받을 수 있나요?', '추가 장착한 오디오에 대한 보험료를 납입했다면 보상받을 수 있습니다.보험 가입 시 추가 장착 사실을 보험사에 알리고 해당 장치에 대한 보험료를 납입한 경우에만 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '차량을 도난당했는데 보상되나요?', '피보험자동차 전부 도난이라면 자기차량손해로 보상받을 수 있습니다.우선 경찰서에 도난신고를 하고 보험사에 사고접수를 하면 경찰서 신고일로부터 30일 이후 보험금 지급 처리가 가능합니다.단 피보험자동차의 일부인 부분품 부속품 부속기계장치만 도난당했다면 보상되지 않습니다.', '삼성화재'),
('사고접수·보상', '차주가 같은 차량끼리 접촉사고가 났어요. 각 차량의 대물배상으로 보상받을 수 있나요?', '차주가 같은 차량끼리는 대물배상으로 처리할 수 없습니다.대물배상은 피보험자가 다른 사람의 물건을 파손시켜 손해배상책임을 지는 경우에만 보상받을 수 있습니다.단 차량단독사고 보상 특약에 가입했다면 각각의 보험에서 자기차량손해로 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '다른 사람 차를 운전하다가 동승한 차량 소유자가 부상을 입었는데 보상되나요?', '약관상 ''보상하지 아니하는 사유''에 해당하지 않는다면 다른 자동차 운전담보 특약의 자기신체사고 또는 자동차상해 담보로 보상받을 수 있습니다.', '삼성화재'),
('사고접수·보상', '사실혼 관계인 배우자 명의의 차를 운전해도 보상되나요?', '운전자 범위에 배우자가 포함되어 있고 사실혼 배우자 요건에 해당하면 보상받을 수 있습니다.사실혼 관계의 배우자는 자동차보험약관상 ''배우자''의 범위에 포함됩니다.단 사실혼 배우자의 요건에 해당하는지 확인하기 위한 객관적 관계조사가 필요합니다.', '삼성화재'),
('사고접수·보상', '운전자연령한정 특약을 위반하면 보상받을 수 없나요?', '대인배상Ⅰ에 해당하는 담보는 보상받을 수 있습니다.운전자 범위와 연령한정 기준을 위반한 경우 대인배상Ⅰ을 제외한 담보는 보상받을 수 없습니다.단 도난 중 사고에 대해서는 보상이 될 수도 있으니 자세한 내용은 보상담당자에게 확인해 주세요.', '삼성화재'),
('사고접수·보상', '사고를 자기차량손해로 처리했는데 자기부담금을 공제하고 지급되나요?', '자기차량손해로 사고를 처리하면 자기부담금을 제외하고 보험금이 지급됩니다.손해액의 20~30%를 기준으로 설정하신 최소 자기부담금과 최대 자기부담금 100만원 사이에서 자기부담금이 발생합니다.', '삼성화재'),
('사고접수·보상', '다른 사람이 일정 기간 제 차을 운전할때 보험가입은 어떻게 해야 하나요?', '임시운전자 특약에 가입하면 됩니다.임시운전자 특약은 운전자 범위와 연령 범위 제한 없이 누구나 운전할 수 있는 특약입니다.최소 1일부터 최대 30일까지 기간을 선택할 수 있고 가입일 24시부터 종료일24시까지 적용됩니다. 임시운전자 특약은 모니모 앱 또는 홈페이지에서 가입할 수 있습니다. 단 공동소유자가 있는 차량은 홈페이지에서 가입할 수 없으니 담당RC에게 문의해 주세요.바로가기> 임시운전자 특약 가입', '삼성화재'),
('사고접수·보상', '피해자 직접청구란 무엇인가요?', '사고 피해자가 손해배상금을 직접 청구할 수 있는 권리이자 피해자를 위한 보호 조치입니다. 피해자가 직접청구를 하면 보험사는 피보험자 의견 청취 및 통지의 의무가 있습니다.피보험자가 피해자에게 손해배상금을 지급한 사실이 있는지를 확인하기 위해 내용증명우편으로 손해배상지급 청구에 대한 통지서를 발송하는데 이 과정에서 시간이 필요합니다. 따라서 신속한 보험 처리를 원할 경우 사고를 낸 상대측 운전자를 통해 사고접수를 하는 것이 유리할 수 있습니다.', '삼성화재'),
('사고접수·보상', '교통사고 가해자가 보험사에 사고접수를 안 했는데 피해자가 직접 할 수 있나요?', '피해자가 보험사에 직접 사고접수를 할 수 있습니다. 경찰서에 신고해서 ''교통사고 사실확인원''을 발급받고 진단서 등 피해내용을 증명하는 서류를 첨부해 보험자에 직접 청구하면 됩니다.(직접청구제도 활용)', '삼성화재'),
('사고접수·보상', '보험가입이 안 된 자동차로부터 피해를 입었는데 보상받을 수 있나요?', '가해자의 상황과 피해자의 보험가입 여부에 따라 다를 수 있습니다. 보험에 가입되지 않은 무보험차에 의해 피해를 당한 경우 가해자가 손해배상을 하면 다행이지만 변제의사나 능력이 없는 가해자라면 피해자가 자동차보험에 가입되어 있어야 보상받을 수 있습니다. 피해자가 무보험자동차상해(피해자가 사망하거나 다친 경우) 자기차량손해 차량단독사고보상 특약(피보험차량이 파손된 경우)에 가입했다면 보험 가입금액과 자기자동차가액 한도에서 보상을 먼저 받을 수 있습니다. 단 이 경우 는 지급한 보험금에 대해 가해자에게 구상권을 행사합니다.', '삼성화재'),
('사고접수·보상', '자동차 사고를 보험처리하지 않고 개인적으로 하려면 어떻게 하나요?', '보험처리 없이 개인적으로 사고를 처리하려면 피해자와 반드시 합의서를 작성해야 합니다. 개인적으로 사고를 처리하는 경우 나중에 문제가 생길 수 있으므로 합의서를 작성하는 것이 좋습니다.[합의서 포함 내용]- 가해자 및 피해자 인적사항- 사고차량 자동차번호- 사고 일시 및 장소- 합의금액- 청구권 포기 관련 문구(예: 이후 사건에 대해 일체의 권리를 포기하며 민사상/형사상 이의를 제기하지 않겠다.)- 가해자 및 피해자 서명 또는 날인', '삼성화재'),
('사고접수·보상', '책임보험을 가압류할 수 있나요?', '책임보험은 압류 또는 가압류할 수 없습니다.「자동차손해배상 보장법」 제40조(압류 등의 금지)에서 이와 같은 내용을 규정하고 있습니다.서울중앙지방법원 사건(99라7290)에서도 ''종합보험에 지급되는 보험금에 대해서는 압류 또는 가얍류가 가능하지만 책임보험에 대해서는 법률에 따라 압류 또는 가압류를 할 수 없다''고 판시한 바 있습니다.', '삼성화재'),
('긴급출동·차량서비스', 'LPG 차량이 비상급유 요청으로 견인된 경우에도 견인확대 추가 특약이 적용되나요?', 'LPG 차량이 비상급유로 인해 견인된 경우에도 견인확대 추가 특약이 적용됩니다.견인확대 추가 특약을 적용하면 최대 60km까지 견인 서비스를 무상으로 이용할 수 있습니다.', '삼성화재'),
('긴급출동·차량서비스', '견인비가 10만원 이하인데도 보상받을 수 있나요?', '견인비는 금액에 관계없이 지급 조건을 충족하면 보상받을 수 있습니다.교통사고로 인해 운행이 불가능한 상태가 되어 차량을 견인한 경우 약관에서 정한 보상기준에 따라 견인비가 책정됩니다.단 견인비 지급 조건에 해당하지 않으면 금액과 관계없이 보상받을 수 없습니다.', '삼성화재'),
('운전자보험', '개인용 운전자보험에 가입했는데 회사 차를 운전하다가 사고가 났어요. 보상받을 수 있나요?', '개인용 운전자보험은 운전한 차량이 영업용으로 등록된 차량이 아니라면 보상받을 수 있습니다.단 차량손해위로금은 보상 대상에서 제외됩니다.', '삼성화재'),
('운전자보험', '운전자용과 비운전자용 보장내용은 어떻게 다른가요?', '운전 중 발생한 사고의 보상 여부가 다릅니다.운전자용은 운전 중 탑승 중 보행 중 발생한 사고를 모두 보상받을 수 있습니다.비운전자용은 탑승 중 보행 중 사고만 보상되며 운전 중 발생한 사고는 보상받을 수 없습니다.', '삼성화재'),
('운전자보험', '횡단보도 보행자 보호 위반으로 피해자가 사망한 경우 중상해 교통사고처리지원금 담보만으로 보상받을 수 있나요?', '아니요 보상받을 수 없습니다.중상해 교통사고처리지원금 담보는 피해자 사망이 포함되지 않고 중과실에서 제외되기 때문에 횡단보도 위반 피해자 사망 사고 시 중상해 교통사고처리지원금 담보만 가입되었다면 보상 청구할 수 없습니다.', '삼성화재'),
('운전자보험', '렌터카나 회사차량을 운전하다가 사고가 났을 때 운전자보험으로 보상받을 수 있나요?', '운전자보험은 피보험자가 본인 소유가 아닌 차량을 운전하더라도 보험금을 청구할 수 있습니다.단 ''운전중 돌발사고 수리비용지원금'' ''차대차사고차량 시세하락 손실지원금'' ''차량유리 교체비용지원금'' 등 수리비용관련 담보는 증권에 기재된 자동차(피보험자 본인이 개인명의로 소유하거나 또는 개인명의로 리스한 자동차로 사고발생 당시 피보험자가 사용 또는 관리하는 자동차로 영업 목적의 자동차는 제외)일 경우에만 가능합니다.', '삼성화재'),
('운전자보험', '운전자보험과 자동차보험은 무엇이 다른가요?', '운전자보험은 자동차사고로 인한 상해 및 비용을 강화한 보험입니다.특히 운전자의 신체상해 보상과 운전 중 여러 가지 사고에 대한 비용을 보상하고 아래와 같이 자동차보험에서 보상하지 않는 위험까지 보상합니다.[운전자보험 보상범위]- 운전 중 사고로 다른 사람의 신체에 상해를 입힘으로써 부과되는 벌금- 사고로 인한 면허정지 및 취소에 대한 위로금- 운전 중 사고로 입원한 경우 생활유지비- 운전 중 방어비용 형사합의지원금 자동차보험료할증지원금- 운전 중 사고로 차량이 전손되거나 차량을 도난당한 경우의 차량대체비용 지원- 교통사고처리지원금', '삼성화재'),
('운전자보험', '운전자보험 가입자인데 폐차했어요. 차량손해위로금 50만원을 받을 수 있나요?', '사고와 관련 없는 단순 폐차라면 보상받을 수 없습니다.운전자보험의 차량손해위로금은 아래에 해당하는 경우에만 보상받을 수 있습니다.- 운행 중 사고로 차량이 전손된 경우- 차량을 도난당해 회수하지 못한 경우단 보험증권에 기재된 본인 및 배우자 소유의 차량이어야 합니다.', '삼성화재'),
('운전자보험', '자동차사고로 수리비가 차량 가격보다 더 나왔는데 폐차하지 않고 수리해도 운전자보험의 차량손해위로금을 받을 수 있나요?', '네 받을 수 있습니다.실제 폐차 여부와 관계없이 차량 수리비가 자동차가액보다 많은 경우에는 전손(전체 손실)으로 인정될 수 있습니다.따라서 보험증권에 기재된 차량이라면 운전자보험의 차량손해위로금을 청구할 수 있습니다.', '삼성화재'),
('운전자보험', '자동차보험과 운전자보험에서 벌금 특약에 모두 가입했는데 중복 보상되나요?', '아니요 중복 보상되지 않습니다.자동차보험과 운전자보험의 벌금 특약은 비례보상이 적용되어 각 보험의 보상비율에 따라 나누어 보상됩니다.', '삼성화재'),
('운전자보험', '약식기소 결과 벌금형을 선고받았어요. 자동차보험에 법률지원 특약이 있으면 운전자보험과 비례보상되나요?', '자동차보험에 법률지원 특약이 있으면 운전자보험(실손상품)과 비례보상받을 수 있습니다.또한 다른 보험사에서 벌금 관련 담보를 추가로 가입했다면 함께 비례보상됩니다.', '삼성화재');

-- ===== 뷰 =====
-- 연도 · 명절별 전국 합계 · 일평균 · 치사율(사고 100건당 사망자)
CREATE VIEW v_holiday_totals AS
SELECT year, holiday,
       COUNT(*)                                   AS days,
       SUM(accidents)                             AS accidents,
       SUM(deaths)                                AS deaths,
       SUM(serious)                               AS serious,
       SUM(injuries)                              AS injuries,
       ROUND(SUM(accidents) / COUNT(*), 1)        AS accidents_per_day,
       ROUND(SUM(deaths) / SUM(accidents) * 100, 2) AS fatality_rate
FROM accident_daily
WHERE level = '전국'
GROUP BY year, holiday;

-- 연도 · 명절 · 시도별 합계 (시도 소계 행 기준)
CREATE VIEW v_sido_totals AS
SELECT year, holiday, sido,
       COUNT(*) AS days, SUM(accidents) AS accidents, SUM(deaths) AS deaths,
       SUM(serious) AS serious, SUM(injuries) AS injuries
FROM accident_daily
WHERE level = '시도'
GROUP BY year, holiday, sido;

-- 전국 일자별 + 명절 당일 기준 D (0 = 당일, -1 = 전날, +1 = 다음날)
CREATE VIEW v_daily_d AS
SELECT a.year, a.holiday, a.acc_date, a.weekday,
       DATEDIFF(a.acc_date, h.d_day) AS d_offset,
       a.accidents, a.deaths, a.serious, a.injuries
FROM accident_daily a
JOIN holiday_dates h ON h.year = a.year AND h.holiday = a.holiday
WHERE a.level = '전국';

-- ===== 확인용 (실행 결과가 아래 숫자와 같으면 정상) =====
SELECT 'accident_daily' AS tbl, COUNT(*) AS n FROM accident_daily   -- 8901
UNION ALL SELECT 'holiday_dates', COUNT(*) FROM holiday_dates        -- 10
UNION ALL SELECT 'hotspot', COUNT(*) FROM hotspot                    -- 81
UNION ALL SELECT 'sido_boundary', COUNT(*) FROM sido_boundary        -- 17
UNION ALL SELECT 'faq', COUNT(*) FROM faq;                           -- 348

